import { View, Text } from '@tarojs/components'
import type { CommentNode, FlattenedReply } from '@/types'
import Avatar from '@/components/Avatar'
import { forumDetailLabels } from '@/labels/forumDetail'
import { formatTime } from '@/utils/formatTime'
import './index.css'

interface CommentItemProps {
  comment: CommentNode | FlattenedReply
  isReply?: boolean
  replyToNickname?: string
  isMine?: boolean
  /** 是否允许编辑（交流帖 true / 预测帖 false，后端无接口） */
  canEdit?: boolean
  /** 是否允许删除（交流帖 true / 预测帖 false，后端无接口） */
  canDelete?: boolean
  onReply: (comment: CommentNode) => void
  onEdit: (comment: CommentNode) => void
  onDelete: (comment: CommentNode) => void
  onLike: (comment: CommentNode) => void
  onCollect: (comment: CommentNode) => void
}

/** 单条评论：头像 + 昵称/时间 + 内容 + 操作行（点赞/收藏/回复/编辑/删除） */
export default function CommentItem({
  comment,
  isReply = false,
  replyToNickname,
  isMine = false,
  canEdit = true,
  canDelete = true,
  onReply,
  onEdit,
  onDelete,
  onLike,
  onCollect,
}: CommentItemProps) {
  const nickname = comment.nickname || forumDetailLabels.anonymous
  const liked = comment.isLike === '1'
  const likeCount = Number(comment.likeNum || 0)
  const collected = comment.isCollect === '1'
  const asNode = comment as CommentNode

  return (
    <View className={`comment-item${isReply ? ' comment-item--reply' : ''}`}>
      <Avatar src={comment.userAvatar} name={nickname} size={isReply ? 28 : 36} />
      <View className='comment-item__body'>
        <View className='comment-item__meta'>
          <Text className='comment-item__nickname'>{nickname}</Text>
          {replyToNickname ? (
            <Text className='comment-item__reply-to'>{forumDetailLabels.replyTo(replyToNickname)}</Text>
          ) : null}
          <Text className='comment-item__time'>{formatTime(comment.createTime)}</Text>
        </View>
        <Text className='comment-item__content'>{comment.content}</Text>
        <View className='comment-item__actions'>
          <Text
            className={`comment-item__action${liked ? ' comment-item__action--active' : ''}`}
            onClick={() => onLike(asNode)}
          >
            {forumDetailLabels.like}
            {likeCount > 0 ? ` ${likeCount}` : ''}
          </Text>
          <Text
            className={`comment-item__action${collected ? ' comment-item__action--active' : ''}`}
            onClick={() => onCollect(asNode)}
          >
            {forumDetailLabels.collect}
          </Text>
          <Text className='comment-item__action' onClick={() => onReply(asNode)}>
            {forumDetailLabels.reply}
          </Text>
          {isMine && canEdit ? (
            <Text className='comment-item__action' onClick={() => onEdit(asNode)}>
              {forumDetailLabels.edit}
            </Text>
          ) : null}
          {isMine && canDelete ? (
            <Text className='comment-item__action comment-item__action--danger' onClick={() => onDelete(asNode)}>
              {forumDetailLabels.delete}
            </Text>
          ) : null}
        </View>
      </View>
    </View>
  )
}
