.hr-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.hr-card {
  margin: 16px;
  padding: 20px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.hr-label {
  display: block;
  margin: 16px 0 8px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
}

.hr-card .hr-label:first-child {
  margin-top: 0;
}

.hr-label-row {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  margin: 16px 0 8px;
}

.hr-label-row .hr-label {
  margin: 0;
  margin-right: 8px;
}

.hr-hint {
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* Chips 单选/多选 */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.chip--active {
  background: var(--color-primary-light);
}

.chip--disabled {
  opacity: 0.45;
}

.chip__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

/* 大底输入 */
.hr-textarea {
  width: 100%;
  min-height: 120px;
  padding: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: 14px;
  box-sizing: border-box;
}

/* 弹层选择触发行 */
.field-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  padding: 0 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.field-row__value {
  font-size: 14px;
  color: var(--color-text);
}

.field-row__value--placeholder {
  color: var(--color-text-placeholder);
}

.field-row__arrow {
  font-size: 16px;
  color: var(--color-text-secondary);
}

/* 操作按钮 */
.hr-actions {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 24px;
}

.hr-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: 999px;
  background: var(--color-primary);
}

.hr-btn--plain {
  background: var(--color-bg);
}

.hr-btn--disabled {
  opacity: 0.6;
}

.hr-btn__text {
  font-size: 15px;
  font-weight: 600;
  color: #fff;
}

.hr-btn__text--plain {
  color: var(--color-text-secondary);
}

/* 结果区 */
.hr-result-head {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: space-between;
}

.hr-result-head .hr-label {
  margin-top: 0;
}

.hr-search {
  height: 44px;
  padding: 0 12px;
  margin-bottom: 12px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: 14px;
}

.rv-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  border-top: 1px solid var(--color-border);
}

.rv-row--head {
  border-top-width: 0; /* RN 端不支持 border-top: none */
}

.rv-row--head .rv-row__issue,
.rv-row--head .rv-row__result,
.rv-row--head .rv-row__pos {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.rv-row__issue {
  width: 28%;
  font-size: 13px;
  color: var(--color-text);
}

.rv-row__result {
  flex: 1;
  font-size: 14px;
  color: var(--color-text);
  letter-spacing: 1px;
}

.rv-row__pos {
  width: 20%;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 1px;
}

.rv-tag {
  min-width: 44px;
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--color-bg);
  font-size: 12px;
  text-align: center;
  color: var(--color-text-secondary);
}

.rv-tag--hit {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.rv-tag--head {
  background: transparent;
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 分组 / 年份卡片 */
.rv-group {
  border-top: 1px solid var(--color-border);
}

.rv-group__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  min-height: 56px;
  padding: 8px 0;
}

.rv-group__range {
  flex: 1;
}

.rv-group__issues {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.rv-group__dates {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.rv-group__stats {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}

.rv-group__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.rv-group__stat--hit {
  color: var(--color-primary);
}

.rv-group__toggle {
  padding: 8px 0 8px 8px;
  font-size: 12px;
  color: var(--color-primary);
}

.rv-group__detail {
  padding-bottom: 12px;
}

.rv-group__detail-title {
  display: block;
  padding: 8px 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
}

/* 命中等级彩球 */
.level-legend {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  padding-bottom: 8px;
}

.level {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 4px;
}

.level__ball {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.level__ball--extreme {
  background: var(--color-primary);
}

.level__ball--high {
  background: var(--color-warning);
}

.level__ball--normal {
  background: var(--color-text-placeholder);
}

.level__ratio {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.level__name {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 加载更多 */
.load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
}

.load-more__text {
  font-size: 13px;
  color: var(--color-primary);
}

/* 底部弹层选择器 */
.sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

.sheet__list {
  max-height: 50vh;
}

.sheet__item {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-top: 1px solid var(--color-border);
}

.sheet__item--active {
  background: var(--color-primary-light);
}

.sheet__item-text {
  font-size: 15px;
  color: var(--color-text);
}

.sheet__item-text--active {
  color: var(--color-primary);
  font-weight: 600;
}
