/* 登录/注册全屏模态页（登录与注册共用同一套类名） */
.auth-page {
  min-height: 100vh;
  background: var(--color-bg-card);
  padding: 0 24px var(--sa-32, calc(32px + env(safe-area-inset-bottom)));
  display: flex;
  flex-direction: column;
}

.auth-page__close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin: 8px 0 0 -12px;
}

.auth-page__close-icon {
  font-size: 18px;
  color: var(--color-text-secondary);
}

.auth-page__title {
  display: block;
  margin: 24px 0 32px;
  font-size: 24px;
  font-weight: 700;
}

.auth-field {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 52px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 16px;
}

.auth-field__input {
  flex: 1;
  height: 52px;
  font-size: 16px;
  color: var(--color-text);
}

.auth-field__toggle {
  padding: 12px 0 12px 16px;
  font-size: 14px;
  color: var(--color-primary);
}

.auth-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin: 8px 0 32px;
}

.checkbox {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 44px;
  margin-bottom: 24px;
}

.checkbox__box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 1px solid var(--color-border);
  border-radius: 4px;
  background: var(--color-bg-card);
}

.checkbox__box--checked {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.checkbox__tick {
  font-size: 13px;
  color: #fff;
  line-height: 1;
}

.checkbox__label {
  margin-left: 8px;
  font-size: 14px;
  color: var(--color-text-secondary);
}

.auth-row__link {
  padding: 12px 0;
  font-size: 14px;
  color: var(--color-text-secondary);
}

.auth-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: 999px;
  background: var(--color-primary);
}

.auth-submit--disabled {
  opacity: 0.6;
}

.auth-submit__text {
  font-size: 16px;
  font-weight: 600;
  color: #fff;
}

.auth-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  margin-top: 24px;
}

.auth-footer__link {
  font-size: 14px;
  color: var(--color-primary);
}
