.forum-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

/* 顶部导航条：分区 Segment + 规则/发帖入口 */
.forum-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  background: var(--color-bg-card);
  padding: 8px 16px;
  gap: 8px;
  margin-bottom: 12px;
}

.forum-segment {
  flex: 1;
  display: flex;
  flex-direction: row;
  gap: 4px;
}

.forum-segment__item {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  border-radius: var(--radius-sm);
}

.forum-segment__item--active {
  background: var(--color-primary-light);
}

.forum-segment__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.forum-segment__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.forum-header__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg);
}

.forum-header__icon-text {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-text-secondary);
}

.forum-header__publish {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--color-primary);
}

.forum-header__publish-text {
  font-size: 14px;
  font-weight: 600;
  color: #fff;
}

/* 底部弹层通用（规则 / 发帖类型） */
.sheet {
  padding: 16px 16px var(--sa-16, calc(16px + env(safe-area-inset-bottom)));
}

.sheet__title {
  display: block;
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

.sheet__rule {
  display: flex;
  align-items: center;
  min-height: 48px;
  border-bottom: 1px solid var(--color-border);
}

.sheet__rule-text {
  font-size: 14px;
  color: var(--color-text);
}

.sheet__action {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  border-bottom: 1px solid var(--color-border);
}

.sheet__action-text {
  font-size: 15px;
  color: var(--color-text);
}

.sheet__cancel {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  margin-top: 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.sheet__cancel-text {
  font-size: 15px;
  color: var(--color-text-secondary);
}

/* 列表底部 */
.list-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
}

.list-footer__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}
