import Taro from '@tarojs/taro'
import { createContext, useCallback, useContext, useEffect, useMemo, useReducer } from 'react'
import type { PropsWithChildren } from 'react'
import type { AuthUserProfile } from '@/types'
import { getToken, setToken, clearToken, setUnauthorizedHandler } from '@/services/request'
import { loginApi, registerApi, fetchProfile } from '@/services/api'

/**
 * 认证全局状态（产品方案 §5.1）：
 * - token 持久化于 storage（「保持登录」默认勾选；不勾选仅存内存，App 进程存活期内有效）
 * - 冷启动 useLaunch → initAuth（读 storage → 拉 profile）
 * - Context + useReducer 管理，不引入重型状态库
 * - 401 清会话并弹登录；403 仅提示
 */

interface AuthState {
  initialized: boolean
  token: string
  profile: AuthUserProfile | null
}

type AuthAction =
  | { type: 'INIT_DONE'; profile: AuthUserProfile | null }
  | { type: 'SET_TOKEN'; token: string }
  | { type: 'SET_PROFILE'; profile: AuthUserProfile | null }
  | { type: 'LOGOUT' }

function reducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case 'INIT_DONE':
      return { ...state, initialized: true, profile: action.profile }
    case 'SET_TOKEN':
      return { ...state, token: action.token }
    case 'SET_PROFILE':
      return { ...state, profile: action.profile }
    case 'LOGOUT':
      return { token: '', profile: null, initialized: true }
    default:
      return state
  }
}

/** 归一化 profile（Web PRD §5.2）：id 必须 >0 否则视为无效；兼容后端蛇形 invi_code */
export function normalizeProfile(raw: any): AuthUserProfile | null {
  if (!raw || typeof raw !== 'object') return null
  const id = Number(raw.id)
  if (!Number.isFinite(id) || id <= 0) return null
  return {
    ...raw,
    id,
    inviCode: raw.inviCode ?? raw.invi_code,
  }
}

export interface AuthContextValue {
  state: AuthState
  isLoggedIn: boolean
  isOperator: boolean
  profile: AuthUserProfile | null
  initAuth: () => Promise<void>
  login: (account: string, passwd: string, remember?: boolean) => Promise<void>
  register: (payload: { account: string; passwd: string; confirmPasswd: string; inviCode?: string }) => Promise<void>
  logout: () => void
  refreshProfile: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue | null>(null)

/** 未登录时跳登录页（全屏模态），可携带回跳地址 */
export function redirectToLogin(redirect?: string) {
  const query = redirect ? `?redirect=${encodeURIComponent(redirect)}` : ''
  Taro.navigateTo({ url: `/pages/login/index${query}` })
}

export function AuthProvider({ children }: PropsWithChildren<{}>) {
  const [state, dispatch] = useReducer(reducer, {
    initialized: false,
    token: '',
    profile: null,
  })

  const doLogout = useCallback(() => {
    clearToken()
    dispatch({ type: 'LOGOUT' })
  }, [])

  useEffect(() => {
    // 网络层 401 → 清除会话
    setUnauthorizedHandler(() => {
      doLogout()
      Taro.showToast({ title: '请重新登录', icon: 'none' })
    })
  }, [doLogout])

  const initAuth = useCallback(async () => {
    const token = await getToken()
    if (!token) {
      dispatch({ type: 'INIT_DONE', profile: null })
      return
    }
    dispatch({ type: 'SET_TOKEN', token })
    try {
      const raw = await fetchProfile()
      dispatch({ type: 'INIT_DONE', profile: normalizeProfile(raw) })
    } catch {
      dispatch({ type: 'INIT_DONE', profile: null })
    }
  }, [])

  const refreshProfile = useCallback(async () => {
    try {
      const raw = await fetchProfile()
      dispatch({ type: 'SET_PROFILE', profile: normalizeProfile(raw) })
    } catch {
      // 静默失败，保留现有 profile
    }
  }, [])

  const login = useCallback(
    async (account: string, passwd: string, remember = true) => {
      const res = await loginApi({ account, passwd })
      const token = String(res?.token || '')
      if (!token) throw new Error('登录失败，请稍后重试')
      // 保持登录：持久化；否则仅存内存（App 进程存活期内有效）
      setToken(token, remember)
      dispatch({ type: 'SET_TOKEN', token })
      await refreshProfile()
    },
    [refreshProfile],
  )

  const register = useCallback(
    async (payload: { account: string; passwd: string; confirmPasswd: string; inviCode?: string }) => {
      await registerApi(payload)
      // 注册成功自动登录（remember=true）
      await login(payload.account, payload.passwd, true)
    },
    [login],
  )

  const value = useMemo<AuthContextValue>(
    () => ({
      state,
      isLoggedIn: !!state.profile,
      isOperator: state.profile?.operatorFlag === 1,
      profile: state.profile,
      initAuth,
      login,
      register,
      logout: doLogout,
      refreshProfile,
    }),
    [state, initAuth, login, register, doLogout, refreshProfile],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth 必须在 <AuthProvider> 内使用')
  return ctx
}
