/**
 * Java 后端（lottery_6，RuoYi 风格，无 context-path）接口全量清单。
 * App 端已改为直连后端：原 Nuxt BFF（lottery_web server/api/*）的服务端加工
 * （字段重命名、排序、聚合、参数白名单等）移植到本文件及同目录 drawResults.ts /
 * profileDashboard.ts。普通接口返回 AjaxResult {code,msg,data}（code 200 成功），
 * 分页接口返回 TableDataInfo（code 0/200 均成功，rows/total 双结构），由 request.ts 统一解包。
 * 公共只读接口（开奖/榜单/信息流/论坛/评论等无需登录页面的数据源）统一带 silent401：
 * 本地残留失效 token 时只抛错给页面降级，不清会话、不把公开页用户踢去登录。
 */

/** 把可选参数拼成 query 字符串（用于「POST 且参数走 query」的后端接口） */
function buildQuery(params: Record<string, any>) {
  const search = Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&')
  return search ? `?${search}` : ''
}

// ---------- 认证 ----------

function looksLikeToken(value: string) {
  return value.split('.').length === 3 || value.length > 40
}

export async function loginApi(body: { account: string; passwd: string }) {
  const account = String(body?.account || '').trim()
  const passwd = String(body?.passwd || '').trim()
  if (!account || !passwd) {
    throw new ApiError('请输入账号和密码', 400)
  }

  // 后端登录响应结构不固定（token 可能在 data 或 msg），需要完整 AjaxResult，
  // 不走 request.ts 的 data 解包，参照 uploadAvatar 直接发请求
  const Taro = (await import('@tarojs/taro')).default
  const res = await Taro.request({
    url: `${XHS_API_BASE}/biz/user/login`,
    method: 'POST',
    data: { account, passwd },
    timeout: 15000,
  })
  const result = res.data as any

  const dataToken = typeof result?.data === 'string' ? result.data.trim() : ''
  const msgToken = typeof result?.msg === 'string' ? result.msg.trim() : ''
  const token =
    (looksLikeToken(dataToken) ? dataToken : '') ||
    (looksLikeToken(msgToken) ? msgToken : '') ||
    dataToken ||
    msgToken

  if (Number(result?.code ?? 500) !== 200 || !token) {
    throw new ApiError(
      typeof result?.msg === 'string' && result.msg ? result.msg : '登录失败',
      401,
      result?.code,
      result,
    )
  }
  return { token }
}

export async function registerApi(body: { account: string; passwd: string; confirmPasswd: string; inviCode?: string }) {
  const account = String(body?.account || '').trim()
  const passwd = String(body?.passwd || '').trim()
  const confirmPasswd = String(body?.confirmPasswd || '').trim()
  const inviCode = String(body?.inviCode || '').trim()

  if (!account || !passwd || !confirmPasswd) {
    throw new ApiError('请输入账号和密码', 400)
  }
  // 两次密码一致性校验（原 BFF 在服务端校验，现移植到客户端）
  if (passwd !== confirmPasswd) {
    throw new ApiError('两次输入的密码不一致', 400)
  }

  const result = await post<any>('/biz/user/register', {
    account,
    passwd,
    confirmPasswd,
    ...(inviCode ? { inviCode } : {}),
  })
  return {
    message: typeof result?.msg === 'string' ? result.msg : '注册成功',
  }
}

