const BANNER_LINK_TYPES = ['none', 'page', 'url'] as const

/**
 * 首页轮播图（GET /banner/list，契约见 docs/home-banner-api-spec.md）。
 * 归一化：过滤无图项、/ 开头相对路径拼 XHS_API_BASE（RuoYi 上传目录 /profile/upload）、
 * 非法 linkType 降级 none、sort 升序、最多 8 张。
 */
export async function fetchBannerList(position = 'home_top'): Promise<BannerItem[]> {
  const resp = await get<any>('/banner/list', { position }, { silent401: true })
  const list = Array.isArray(resp) ? resp : []
  return list
    .filter((item: any) => item && item.imageUrl)
    .map((item: any) => {
      const rawUrl = String(item.imageUrl).trim()
      return {
        id: Number(item.id),
        title: item.title ? String(item.title) : '',
        imageUrl: rawUrl.startsWith('/') ? `${XHS_API_BASE}${rawUrl}` : rawUrl,
        linkType: (BANNER_LINK_TYPES.includes(item.linkType) ? item.linkType : 'none') as BannerItem['linkType'],
        linkUrl: item.linkUrl ? String(item.linkUrl).trim() : '',
        sort: Number(item.sort ?? 0),
      }
    })
    .sort((a, b) => a.sort - b.sort)
    .slice(0, 8)
}

