export async function fetchLatestDraw(code: string): Promise<LotteryDraw> {
  const lotteryCode = String(code || '350133')
  try {
    const resp = await get<any>('/lotteryInfo/dailyDetail', { code: lotteryCode }, { silent401: true })
    const data = unwrapAjaxData<any>(resp) || {}

    // 后端 history 不保证按期数倒序，统一排序
    const history = (Array.isArray(data.history) ? data.history : [])
      .map((item: any) => ({
        drawNum: String(item?.drawNum || '').trim(),
        numbers: safeSplitNumbers(item?.result),
        drawTime: String(item?.drawTime || '').trim(),
      }))
      .filter((item: { drawNum: string; numbers: string[] }) => item.drawNum && item.numbers.length)
      .sort((left: { drawNum: string }, right: { drawNum: string }) =>
        right.drawNum.localeCompare(left.drawNum, undefined, { numeric: true }),
      )

    // 后端 latest* 字段可能滞后于 history（实测如此），优先取排序后的 history 第一条
    const latest = history[0] || {
      drawNum: String(data.latestDrawNum || '').trim(),
      numbers: safeSplitNumbers(data.latestResult),
      drawTime: String(data.latestDrawTime || '').trim(),
    }

    return {
      lotteryType: String(data.lotteryName || '').trim(),
      lotteryCode,
      drawNum: latest.drawNum,
      numbers: latest.numbers,
      drawTime: latest.drawTime,
      // 首页只展示前 10 条，截断到 20 条以限制响应体积（沿用 BFF 行为）
      history: history.slice(0, 20),
    }
  } catch {
    return {
      lotteryType: '',
      lotteryCode,
      drawNum: '',
      numbers: [],
      drawTime: '',
      history: [],
    }
  }
}

export async function fetchDrawDailyDetail(code: string, size?: number): Promise<DrawDailyDetail> {
  const lotteryCode = String(code || '350133')
  const requestedSize = Number(size || 120)
  const pageSize = Number.isFinite(requestedSize)
    ? Math.min(200, Math.max(1, Math.floor(requestedSize)))
    : 120

  try {
    const [{ rows: history, total }, liveSource] = await Promise.all([
      fetchDrawResultsPage(lotteryCode, pageSize),
      fetchDrawLiveSource(lotteryCode).catch(() => null),
    ])
    const latest = history[0]
    return {
      lotteryType: latest?.lotteryType || '',
      lotteryCode: latest?.lotteryCode || lotteryCode,
      drawNum: latest?.drawNum || '',
      numbers: latest?.numbers || [],
      drawTime: latest?.drawTime || '',
      history,
      // 该彩种开奖记录总数（历史总期数），供前端计算「全部」回看窗口的实际期数
      total,
      liveSource: liveSource || undefined,
    }
  } catch {
    return {
      lotteryType: '',
      lotteryCode,
      drawNum: '',
      numbers: [],
      drawTime: '',
      history: [],
      total: 0,
      liveSource: undefined,
    }
  }
}

export async function fetchDrawHistory(code: string, pageNum: number, pageSize = 20) {
  const lotteryCode = String(code || '350133')
  const page = Math.max(1, Math.floor(Number(pageNum || 1)) || 1)
  const size = Math.min(100, Math.max(1, Math.floor(Number(pageSize || 20)) || 20))

  try {
    const data = await get<{ rows: any[]; total: number }>(
      '/lotteryInfo/getLotteryList',
      { code: lotteryCode, pageNum: page, pageSize: size },
      { paged: true, silent401: true },
    )
    // 实测后端行序并非严格期数倒序（且跨页有重复期号），至少在页内按期数倒序展示
    const rows = (data.rows || [])
      .map((item: any) => ({
        drawNum: String(item?.lotteryDrawNum || ''),
        numbers: safeSplitNumbers(item?.lotteryDrawResult),
      }))
      .sort((left: { drawNum: string }, right: { drawNum: string }) =>
        right.drawNum.localeCompare(left.drawNum, undefined, { numeric: true }),
      )
    return { rows, total: Number(data.total) || 0, pageNum: page, pageSize: size }
  } catch {
    return { rows: [], total: 0, pageNum: page, pageSize: size }
  }
}

