export interface ExpertRankQuery {
  rankType?: string
  lotteryCode?: string
  forecastPhase?: string
  valueType?: string
  planMode?: string
  codeMode?: string
  scaleSize?: string
  precision?: string
  identity?: string
  followFilter?: string
  rankCategory?: string
}

function parseWinRate(result?: string): number {
  if (!result) return 0
  // 格式: "10次5中" → winRate = 5/10 * 100
  const m = result.match(/(\d+)次(\d+)中/)
  if (m) {
    const total = parseInt(m[1], 10)
    const hit = parseInt(m[2], 10)
    if (total > 0) return Math.round((hit / total) * 100)
  }
  return 0
}

export async function fetchExpertRank(query: ExpertRankQuery): Promise<Expert[]> {
  try {
    // 参数白名单 / 默认值（移植自 BFF rank.get.ts）
    const params: Record<string, any> = {
      rankType: String(query.rankType || '10'),
      lotteryCode: String(query.lotteryCode || '350133'),
    }
    const forecastPhase = String(query.forecastPhase || '').trim()
    const valueType = String(query.valueType || '').trim()
    const planMode = String(query.planMode || '').trim()
    const codeMode = String(query.codeMode || '').trim()
    const scaleSize = String(query.scaleSize || '').trim()
    const precision = String(query.precision || '').trim()
    const identity = String(query.identity || '').trim()
    const followFilter = String(query.followFilter || '').trim()
    const rankCategory = String(query.rankCategory || '').trim()
    if (forecastPhase === '0' || forecastPhase === '1') params.forecastPhase = forecastPhase
    if (valueType === '0') params.valueType = valueType
    if (planMode) params.planMode = planMode
    if (codeMode) params.codeMode = codeMode
    if (scaleSize) params.scaleSize = scaleSize
    if (precision) params.precision = precision
    if (identity) params.identity = identity
    if (followFilter === 'followed' || followFilter === 'unfollowed') params.followFilter = followFilter
    if (rankCategory === 'winRate' || rankCategory === 'subscribe') params.rankCategory = rankCategory

    // followFilter 依赖登录态，request.ts 会自动带 bizAuthorization；未登录时后端自动忽略该参数
    const resp = await get<any>('/forecast/rank/getRankList', params, { silent401: true })
    const rows = Array.isArray(unwrapAjaxData<any>(resp)) ? unwrapAjaxData<any[]>(resp) : []
    if (!rows.length) return []

    return rows.map((item: any, index: number): Expert => {
      const result = String(item.result || '--')
      return {
        id: Number(item.userId || item.bizUserId || index + 1),
        nickName: String(item.userNickName || `达人${index + 1}`),
        avatar: String(item.userAvatar || ''),
        isVerified: String(item.identity || '').toUpperCase() === 'T',
        winRate: parseWinRate(result),
        // 后端无对应字段，沿用 BFF 的硬编码占位
        consecutiveWins: 0,
        totalEvaluations: 0,
        rating: 4.5,
        rank: Number(item.sort || index + 1),
        lastDrawNum: String(item.drawNum || ''),
        record: result,
        recentTrend: 'stable',
        // 后端可能返回 true/1/'1'，字符串 '0' 用 Boolean 会误判为 true
        isFollowed: item.isFollowed === true || item.isFollowed === 1 || item.isFollowed === '1',
        fanCount: Number(item.fanCount || 0),
        rankBadge: index < 3 ? index + 1 : undefined,
      }
    })
  } catch {
    return []
  }
}

export interface ExpertHistoryQuery {
  userId: number | string
  lotteryCode?: string
  mode?: 'plan' | 'single'
  dimension?: string
  precision?: string
  chasePeriods?: string
  rounds?: number
}

export async function fetchExpertHistory(query: ExpertHistoryQuery): Promise<ExpertPlanCycle[]> {
  const userId = Number(query.userId || 1)
  const requestedMode = String(query.mode || 'plan')

  const params: Record<string, any> = {
    userId,
    lotteryCode: String(query.lotteryCode || '350133'),
    mode: requestedMode,
    rounds: Number(query.rounds || 10),
  }
  if (query.dimension) params.dimension = String(query.dimension)
  if (query.precision) params.precision = String(query.precision)
  if (query.chasePeriods) params.chasePeriods = Number(query.chasePeriods)

  try {
    const resp = await get<any>('/forecast/expert/planCycles', params, { silent401: true })
    const data = unwrapAjaxData<any>(resp)
    const rows = Array.isArray(data) ? data : []
    // 与 BFF 的差异：BFF 空数据/异常时返回硬编码 mock（fallbackCycles），App 端不移植 mock，统一返回空数组
    if (!rows.length) return []
    return rows.map((item: any): ExpertPlanCycle => ({
      id: String(item.planId),
      expertId: userId,
      mode: requestedMode === 'single' ? 'single' : 'plan',
      dimension: String(item.dimension || '五定'),
      precision: String(item.precision || '7*7*7*7*7'),
      chasePeriods: `追${item.chasePeriods || 8}期`,
      periodRange: String(item.periodRange || ''),
      planName: String(item.planName || ''),
      planCode: String(item.displayPlanCode || item.planCode || ''),
      resultLabel: String(item.resultLabel || '×'),
      issues: Array.isArray(item.issues)
        ? item.issues.map((issue: any) => ({
          issue: String(issue.drawNum || issue.issue || ''),
          numbers: safeSplitNumbers(String(issue.drawResult || '')).slice(0, 5),
          hit: String(issue.hitFlag || '').toLowerCase() === 'hit',
        }))
        : [],
    }))
  } catch {
    return []
  }
}

