export interface ForecastPublishPayload {
  title: string
  lotteryCode: string
  forecastPhase: '0' | '1'
  planNum?: number
  lotteryDrawNum?: string
  sourceType: 'F'
  planVOList: Record<string, any>[]
}

const FORECAST_LOTTERY_CODES = new Set(['04', '350133', '3d'])

/** 去除空串/null/undefined 字段，字符串统一 trim（移植自 BFF） */
function compactRecord(raw: Record<string, any>) {
  return Object.entries(raw).reduce<Record<string, any>>((acc, [key, value]) => {
    if (value === undefined || value === null) return acc
    if (typeof value === 'string' && !value.trim()) return acc
    acc[key] = typeof value === 'string' ? value.trim() : value
    return acc
  }, {})
}

/** 发布/编辑预测帖共用的校验与归一化（移植自 BFF publish-prediction/edit-prediction） */
function normalizeForecastPayload(body: ForecastPublishPayload & { id?: number | string }) {
  const lotteryCode = String(body?.lotteryCode || '').trim()
  const forecastPhase = String(body?.forecastPhase || '0').trim() === '1' ? '1' : '0'
  const planNum = Number(body?.planNum || 0)
  const lotteryDrawNum = String(body?.lotteryDrawNum || '').trim()
  const sourceType = String(body?.sourceType || 'F').trim() || 'F'
  const planVOList = Array.isArray(body?.planVOList) ? body.planVOList : []

  if (!FORECAST_LOTTERY_CODES.has(lotteryCode)) {
    throw new ApiError('Invalid lotteryCode', 400)
  }
  if (!planVOList.length) {
    throw new ApiError('planVOList is required', 400)
  }
  if (forecastPhase === '0' && !lotteryDrawNum) {
    throw new ApiError('lotteryDrawNum is required for single phase', 400)
  }
  // 客户端按维度收紧到 3~6 / 3~8；此处不感知维度，按并集上下界兜底校验
  if (forecastPhase === '1' && (planNum < PLAN_NUM_MIN || planNum > PLAN_NUM_MAX)) {
    throw new ApiError(`planNum must be ${PLAN_NUM_MIN}~${PLAN_NUM_MAX} for plan phase`, 400)
  }

  const title = String(body?.title || '').trim()
  const payload: Record<string, any> = {
    title: title || undefined,
    lotteryCode,
    forecastPhase,
    sourceType,
    planVOList: planVOList.map((plan) => compactRecord(plan)),
  }
  if (body.id !== undefined) payload.id = Number(body.id)
  if (forecastPhase === '1') payload.planNum = planNum
  if (forecastPhase === '0' && lotteryDrawNum) payload.lotteryDrawNum = lotteryDrawNum
  return payload
}

export async function publishPrediction(body: ForecastPublishPayload) {
  const result = await post<any>('/forecast/add', normalizeForecastPayload(body))
  return {
    success: true,
    message: typeof result?.msg === 'string' && result.msg.trim() ? result.msg : '发布成功',
  }
}

export async function editPrediction(body: ForecastPublishPayload & { id: number | string }) {
  const result = await put<any>('/forecast/edit', normalizeForecastPayload(body))
  return {
    success: true,
    message: typeof result?.msg === 'string' && result.msg.trim() ? result.msg : '更新成功',
  }
}

export interface IssueItem {
  lotteryCode: string
  rawKey: string
  drawNum: string
  label: string
}

type ForecastIssueMap = Record<string, Array<Record<string, string>>>

function normalizeIssueMap(raw: unknown): ForecastIssueMap {
  if (!raw || typeof raw !== 'object') return {}
  const result: ForecastIssueMap = {}
  Object.entries(raw as Record<string, unknown>).forEach(([key, value]) => {
    if (!Array.isArray(value)) return
    result[key] = value.filter((item) => item && typeof item === 'object') as Array<Record<string, string>>
  })
  return result
}

function normalizeIssueList(issueMap: ForecastIssueMap, targetLotteryCode = ''): IssueItem[] {
  const list: IssueItem[] = []
  const keys = targetLotteryCode ? [targetLotteryCode] : Object.keys(issueMap)
  keys.forEach((lotteryCode) => {
    const rows = Array.isArray(issueMap[lotteryCode]) ? issueMap[lotteryCode] : []
    rows.forEach((row) => {
      Object.entries(row).forEach(([rawKey, label]) => {
        const drawNum = rawKey.includes('-') ? rawKey.split('-').slice(1).join('-') : rawKey
        list.push({ lotteryCode, rawKey, drawNum, label: String(label || '') })
      })
    })
  })
  return list
}

/** 后端开奖历史为空时会抛「Index: 0, Size: 0」，按空数据降级 */
function isEmptyHistoryError(error: any) {
  const raw = error?.data?.msg || error?.data?.message || error?.message || ''
  return /Index:\s*0,\s*Size:\s*0/i.test(String(raw))
}

export async function fetchForumIssues(lotteryCode: string) {
  const code = String(lotteryCode || '').trim()
  let issueMap: ForecastIssueMap = {}
  try {
    const resp = await post<any>('/forecast/getIssueList', code ? { lotteryCode: code } : {})
    issueMap = normalizeIssueMap(unwrapAjaxData(resp))
  } catch (error: any) {
    if (!isEmptyHistoryError(error)) throw error
    issueMap = {}
  }
  return {
    lotteryCode: code,
    map: issueMap,
    list: normalizeIssueList(issueMap, code),
  }
}

export async function fetchForumTerm(lotteryCode: string) {
  const code = String(lotteryCode || '').trim()
  let map: Record<string, string> = {}
  try {
    const resp = await post<any>('/forecast/getTermNum', code ? { lotteryCode: code } : {})
    const data = unwrapAjaxData(resp)
    if (data && typeof data === 'object') {
      map = Object.entries(data as Record<string, unknown>).reduce<Record<string, string>>((acc, [key, value]) => {
        const normalized = String(value || '').trim()
        if (normalized) acc[key] = normalized
        return acc
      }, {})
    }
  } catch (error: any) {
    if (!isEmptyHistoryError(error)) throw error
    map = {}
  }
  return {
    lotteryCode: code,
    map,
    current: code ? String(map[code] || '') : '',
  }
}

