export async function fetchUserInfo(id: number | string): Promise<UserPublicInfo | null> {
  const resp = await get<any>(`/biz/userInfo/getUserInfo/${id}`, undefined, { silent401: true })
  const payload = unwrapAjaxData<Record<string, unknown> | null>(resp)
  // 用户不存在 / 后端返回空 data 时归一化为 null
  if (!payload) return null
  const userId = Number(payload.id)
  if (!Number.isFinite(userId) || userId <= 0) return null
  return {
    id: userId,
    nickname: typeof payload.nickname === 'string' ? payload.nickname : '',
    avatar: typeof payload.avatar === 'string' ? payload.avatar : '',
    identity: typeof payload.identity === 'string' ? payload.identity : '',
    memberFlag: Number(payload.memberFlag ?? 0),
    followerCount: Number(payload.followerCount ?? 0),
    followingCount: Number(payload.followingCount ?? 0),
    forumCount: Number(payload.forumCount ?? 0),
    forecastCount: Number(payload.forecastCount ?? 0),
    isFollowing: Boolean(payload.isFollowing),
  }
}

