export function updateUserInfo(body: { nickname?: string; avatar?: string; phone?: string; address?: string }) {
  // 仅允许修改非敏感字段，避免透传 id/passwd/parentId 等字段造成越权或误改
  const filteredBody: Record<string, any> = {}
  for (const key of ['nickname', 'avatar', 'phone', 'address'] as const) {
    if (Object.prototype.hasOwnProperty.call(body, key)) {
      filteredBody[key] = body[key]
    }
  }
  return post('/biz/userInfo/updateBizInfo', filteredBody)
}

export async function uploadAvatar(filePath: string): Promise<string> {
  const Taro = (await import('@tarojs/taro')).default
  const { getToken } = await import('./request')
  const res = await Taro.uploadFile({
    url: `${XHS_API_BASE}/biz/userInfo/uploadAvatar`,
    filePath,
    name: 'file',
    header: { bizAuthorization: await getToken() },
  })
  // 后端返回 AjaxResult，data 为头像 URL 字符串
  const body = JSON.parse(res.data || '{}')
  if (body?.code !== 200 && body?.success !== true) {
    throw new Error(body?.msg || body?.message || '头像上传失败')
  }
  return String(body?.data || '')
}

