// ---------- 工具：历史回查 ----------

/**
 * 拉取某彩种的全部历史开奖记录（去重 + 期数倒序）。
 * 后端 /lotteryInfo/list 含重复期号且排序不严格按期数倒序，需全量拉取后自行去重排序。
 * 与 BFF 的差异：不移植 BFF 的 3 分钟内存缓存（App 端每次实时拉取）。
 */
async function fetchFullDrawHistory(lotteryCode: string): Promise<any[]> {
  const pageSize = 500
  const rows: any[] = []
  const seenIssues = new Set<string>()
  let pageNum = 1
  let total = Number.POSITIVE_INFINITY
  while (rows.length < total) {
    const page = await post<{ rows: any[]; total: number }>(
      `/lotteryInfo/list?pageNum=${pageNum}&pageSize=${pageSize}`,
      { lotteryCode },
      { paged: true, silent401: true },
    )
    const pageRows = Array.isArray(page.rows) ? page.rows : []
    const totalValue = Number(page.total)
    if (Number.isFinite(totalValue) && totalValue >= 0) total = totalValue
    const newRows = pageRows.filter((item: any, index: number) => {
      const issue = String(item?.lotteryDrawNum || `${pageNum}-${index}`)
      if (seenIssues.has(issue)) return false
      seenIssues.add(issue)
      return true
    })
    rows.push(...newRows)
    if (!pageRows.length || !newRows.length) break
    if (!Number.isFinite(total) && pageRows.length < pageSize) break
    pageNum += 1
  }
  return orderHistoryRows(rows)
}

function orderHistoryRows(rows: any[]) {
  return [...rows].sort((left: any, right: any) =>
    String(right.lotteryDrawNum || '').localeCompare(
      String(left.lotteryDrawNum || ''),
      undefined,
      { numeric: true },
    ),
  )
}

/** 期号前 2~4 位推年份（2024001→2024，24001→2024） */
function getIssueYear(issue: string) {
  const digits = issue.replace(/\D/g, '')
  if (/^20\d{2}$/.test(digits.slice(0, 4))) return digits.slice(0, 4)
  return /^\d{2}$/.test(digits.slice(0, 2)) ? `20${digits.slice(0, 2)}` : ''
}

export async function fetchHistoryReview(params: { lotteryCode: string; endIssue?: string; count?: number | string; metadata?: number }) {
  const lotteryCode = String(params.lotteryCode || '')
  const endIssue = String(params.endIssue || '').trim()
  const requestedCount = String(params.count ?? '30')
  const metadataOnly = Number(params.metadata) === 1
  const allPeriods = requestedCount === 'all' || metadataOnly
  const count = allPeriods ? 0 : Math.min(300, Math.max(1, Number(requestedCount) || 30))
  if (!lotteryCode) return { rows: [] as HistoryReviewRow[], message: '彩票类型不能为空' }

  try {
    let orderedRows: any[] = []
    if (allPeriods) {
      orderedRows = await fetchFullDrawHistory(lotteryCode)
    } else {
      const page = await post<{ rows: any[]; total: number }>(
        `/lotteryInfo/list?pageNum=1&pageSize=${Math.min(500, count + 9)}`,
        { lotteryCode },
        { paged: true, silent401: true },
      )
      orderedRows = orderHistoryRows(Array.isArray(page.rows) ? page.rows : [])
    }
    const years = [
      ...new Set(
        orderedRows
          .map((item: any) => getIssueYear(String(item.lotteryDrawNum || '')))
          .filter(Boolean),
      ),
    ].sort((left, right) => right.localeCompare(left))
    if (metadataOnly) return { rows: [] as HistoryReviewRow[], years }
    // 与 BFF 的差异：BFF 在缓存未命中时会 forceRefresh 重试一次；App 端无缓存，本来就是实时全量
    const startIndex = endIssue
      ? orderedRows.findIndex((item: any) => String(item.lotteryDrawNum || '') === endIssue)
      : 0
    if (startIndex < 0) return { rows: [] as HistoryReviewRow[], message: '未找到截至期号，请确认期号格式与历史记录一致' }
    const rows: HistoryReviewRow[] = orderedRows
      .slice(startIndex, allPeriods ? undefined : startIndex + count)
      .map((item: any) => ({
        issue: String(item.lotteryDrawNum || ''),
        result: String(item.lotteryDrawResult || ''),
        drawTime: item.lotteryDrawTime || item.createTime || '',
      }))
    return { rows }
  } catch {
    return { rows: [] as HistoryReviewRow[], message: '历史开奖记录查询失败' }
  }
}
