import { useCallback, useEffect, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro, { usePullDownRefresh, useReachBottom } from '@tarojs/taro'
import { getLotteryMeta } from '@/constants/lottery'
import { fetchPredictionList, fetchUserForumList, fetchUserInfo } from '@/services/api'
import { usePagedList } from '@/hooks/usePagedList'
import { goPostDetail } from '@/utils/nav'
import { formatTime } from '@/utils/formatTime'
import { expertPostsLabels } from '@/labels/rank'
import type { ForecastPost, ForumPost } from '@/types'
import Avatar from '@/components/Avatar'
import LotteryTag from '@/components/LotteryTag'
import HitBadge from '@/components/HitBadge'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import './index.css'

type TabKey = 'exchange' | 'prediction'

/** 预测帖命中标记：优先帖子级 hitFlag，否则取方案级（对齐 Web getHitBadge） */
function resolvePostHitFlag(post: ForecastPost): string | null {
  if (post.hitFlag) return post.hitFlag
  const plans = post.planVOList || []
  for (const plan of plans) {
    const hf = String(plan.hitFlag || '').toLowerCase()
    if (hf === 'hit' || hf === 'success') return 'hit'
    if (hf === 'fail' || hf === 'miss') return 'miss'
  }
  return null
}

/** 维度标签：valueType='0'→号码大底，planMode=-2→杀码，否则选号 */
function resolveDimLabel(post: ForecastPost): string {
  const plan = (post.planVOList || [])[0]
  if (!plan) return expertPostsLabels.dim.pick
  if (String(plan.valueType) === '0') return expertPostsLabels.dim.base
  if (String(plan.planMode) === '-2') return expertPostsLabels.dim.kill
  return expertPostsLabels.dim.pick
}

/** 详情分区 slug：无 code 时回退 pailie5 */
function resolveSlug(code?: string): string {
  return code ? getLotteryMeta(code).slug : 'pailie5'
}

/** 用户帖子列表（Web PRD §6.6）：返回 + 作者昵称 + 双 Tab（交流帖/预测帖），各自上拉加载 + 下拉刷新 */
export default function ExpertPostsPage() {
  const params = Taro.getCurrentInstance().router?.params
  const userId = Number(params?.id) || 0
  const [activeTab, setActiveTab] = useState<TabKey>(params?.tab === 'prediction' ? 'prediction' : 'exchange')
  const [nickname, setNickname] = useState('')

  const exchange = usePagedList<ForumPost>({
    fetchPage: useCallback((pageNum: number) => fetchUserForumList(userId, pageNum, 10), [userId]),
    pageSize: 10,
  })
  const prediction = usePagedList<ForecastPost>({
    fetchPage: useCallback(
      (pageNum: number) => fetchPredictionList({ userId, pageNum, pageSize: 10 }),
      [userId],
    ),
    pageSize: 10,
  })

  // 双 Tab 各自独立加载：切 Tab 时首次激活才拉取
  const loadedRef = useRef<Record<TabKey, boolean>>({ exchange: false, prediction: false })
  useEffect(() => {
    if (!userId || loadedRef.current[activeTab]) return
    loadedRef.current[activeTab] = true
    if (activeTab === 'exchange') exchange.refresh()
    else prediction.refresh()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, userId])

  // 作者昵称：头部标题 + 导航栏标题（失败不阻塞列表）
  useEffect(() => {
    if (!userId) return
    fetchUserInfo(userId)
      .then((info) => {
        const name = info?.nickname?.trim() || ''
        setNickname(name)
        if (name) Taro.setNavigationBarTitle({ title: expertPostsLabels.title(name) })
      })
      .catch(() => {})
  }, [userId])

  usePullDownRefresh(async () => {
    if (activeTab === 'exchange') await exchange.refresh()
    else await prediction.refresh()
    Taro.stopPullDownRefresh()
  })

  useReachBottom(() => {
    const current = activeTab === 'exchange' ? exchange : prediction
    if (current.hasMore && !current.loading) current.loadMore()
  })

  const renderFooter = (list: { loading: boolean; hasMore: boolean; loadMore: () => unknown }) => (
    <View className='list-footer' onClick={() => list.hasMore && !list.loading && list.loadMore()}>
      <Text className='list-footer__text'>
        {list.loading ? '加载中…' : list.hasMore ? '加载更多' : '没有更多了'}
      </Text>
    </View>
  )

  const renderExchange = () => {
    if (exchange.refreshing && exchange.list.length === 0) return <Skeleton rows={5} />
    if (exchange.error && exchange.list.length === 0) {
      return <Empty text={exchange.error} actionText='点击重试' onAction={exchange.refresh} />
    }
    if (exchange.list.length === 0) return <Empty />
    return (
      <>
        {exchange.list.map((post) => {
          const title =
            post.title?.trim() || post.content?.replace(/<[^>]+>/g, '').slice(0, 50) || expertPostsLabels.noTitle
          return (
            <View
              key={post.id}
              className='post-row'
              onClick={() => goPostDetail({ partition: resolveSlug(post.lotteryCode), type: 'exchange', id: post.id })}
            >
              <Text className='post-row__title'>{title}</Text>
              <View className='post-row__meta'>
                <Avatar src={post.userAvatar} name={post.username} size={24} />
                <Text className='post-row__author'>{post.username || expertPostsLabels.anonymous}</Text>
                <LotteryTag code={post.lotteryCode} />
                <Text className='post-row__stat'>{expertPostsLabels.comments(post.commentNum || 0)}</Text>
                <Text className='post-row__stat'>{expertPostsLabels.likes(post.likeNum || 0)}</Text>
                <Text className='post-row__time'>{formatTime(post.createTime)}</Text>
              </View>
            </View>
          )
        })}
        {renderFooter(exchange)}
      </>
    )
  }

  const renderPrediction = () => {
    if (prediction.refreshing && prediction.list.length === 0) return <Skeleton rows={5} />
    if (prediction.error && prediction.list.length === 0) {
      return <Empty text={prediction.error} actionText='点击重试' onAction={prediction.refresh} />
    }
    if (prediction.list.length === 0) return <Empty />
    return (
      <>
        {prediction.list.map((post) => (
          <View
            key={post.id}
            className='pred-card'
            onClick={() => goPostDetail({ partition: resolveSlug(post.lotteryCode), type: 'prediction', id: post.id })}
          >
            <View className='pred-card__head'>
              <Avatar src={post.userAvatar} name={post.nickname} size={32} />
              <View className='pred-card__author'>
                <Text className='pred-card__name'>{post.nickname || expertPostsLabels.anonymous}</Text>
                <Text className='pred-card__time'>{formatTime(post.createTime)}</Text>
              </View>
              <HitBadge hitFlag={resolvePostHitFlag(post)} hitDetail={post.hitDetail} />
            </View>
            <Text className='pred-card__title'>{post.title?.trim() || expertPostsLabels.noTitle}</Text>
            <View className='pred-card__footer'>
              <View className='pred-card__tags'>
                <Text className='pred-card__dim'>{resolveDimLabel(post)}</Text>
                <LotteryTag code={post.lotteryCode} />
              </View>
              <View className='pred-card__stats'>
                <Text className='pred-card__stat'>{expertPostsLabels.collects(post.collectNum || 0)}</Text>
                <Text className='pred-card__stat'>{expertPostsLabels.comments(post.commentNum || 0)}</Text>
              </View>
            </View>
          </View>
        ))}
        {renderFooter(prediction)}
      </>
    )
  }

  return (
    <View className='posts-page'>
      {/* 作者昵称标题（返回由导航栏返回键承担） */}
      <Text className='posts-page__title'>
        {nickname ? expertPostsLabels.title(nickname) : expertPostsLabels.fallbackTitle}
      </Text>

      {/* 双 Tab 分段 */}
      <View className='tabs'>
        {(['exchange', 'prediction'] as TabKey[]).map((tab) => (
          <View
            key={tab}
            className={`tabs__item${activeTab === tab ? ' tabs__item--active' : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            <Text className={`tabs__text${activeTab === tab ? ' tabs__text--active' : ''}`}>
              {tab === 'exchange' ? expertPostsLabels.exchangeTab : expertPostsLabels.predictionTab}
            </Text>
          </View>
        ))}
      </View>

      {activeTab === 'exchange' ? renderExchange() : renderPrediction()}
    </View>
  )
}
