import { Text } from '@tarojs/components'
import { resolveHitStatus } from '@/constants/lottery'
import { forumLabels } from '@/labels'
import './index.css'

interface HitBadgeProps {
  hitFlag?: string | null
  hitDetail?: string | null
}

function parseOverall(hitDetail?: string | null): string | null {
  if (!hitDetail) return null
  try {
    const parsed = JSON.parse(hitDetail)
    return parsed?.overall ?? null
  } catch {
    return null
  }
}

/** 命中徽章：已命中绿 / 未命中红 / 进行中橙 */
export default function HitBadge({ hitFlag, hitDetail }: HitBadgeProps) {
  const status = resolveHitStatus(hitFlag, parseOverall(hitDetail))
  if (status === 'hit') return <Text className='hit-badge hit-badge--hit'>{forumLabels.hitBadge}</Text>
  if (status === 'miss') return <Text className='hit-badge hit-badge--miss'>{forumLabels.missBadge}</Text>
  return <Text className='hit-badge hit-badge--pending'>{forumLabels.pendingBadge}</Text>
}
