.follow-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 96px;
  min-height: 48px;
  padding: 0 20px;
  border-radius: 999px;
  font-size: 13px;
  color: var(--color-primary);
  border: 1px solid var(--color-primary);
}

.follow-btn--active {
  color: var(--color-text-secondary);
  border-color: var(--color-border);
  background: var(--color-bg);
}
