import { AVATAR_COLORS } from '@/constants/lottery'

/** 头像兜底文字：昵称末两位 */
export function avatarText(name?: string) {
  return (name || 'U').slice(-2)
}

/** 头像兜底色：按昵称首字取模，保证同一用户颜色稳定 */
export function avatarBg(name?: string) {
  const code = (name || '').charCodeAt(0) || 0
  return AVATAR_COLORS[code % AVATAR_COLORS.length]
}
