type PostType = 'exchange' | 'prediction'
type PostData = ForumPost & ForecastPost

const POSITION_LETTERS = ['A', 'B', 'C', 'D', 'E', 'F', 'G']

/** 帖子作者 id：交流帖 userId / 预测帖 bizUserId */
function authorIdOf(post: PostData | null): number | null {
  const id = Number(post?.bizUserId || post?.userId || 0)
  return id > 0 ? id : null
}

// ---------- 预测方案展示辅助（移植自 lottery_web detail 页） ----------

function parseHitDetail(plan: ForecastPlanPayload): Record<string, any> | null {
  try {
    if (plan.hitDetail) return typeof plan.hitDetail === 'string' ? JSON.parse(plan.hitDetail) : plan.hitDetail
  } catch {
    // ignore parse error
  }
  return null
}

function isFreeMode(plan: ForecastPlanPayload) {
  return String(plan.valueType) === '0'
}

function freeModeTokens(plan: ForecastPlanPayload): string[] {
  return String(plan.diffuseValue || '')
    .trim()
    .split(/[\s,，;；]+/)
    .filter(Boolean)
}

/** 已结算 = hitFlag 已判定，或已有开奖结果/命中详情 */
function isPlanSettled(plan: ForecastPlanPayload) {
  const flag = String(plan.hitFlag || '').trim().toLowerCase()
  if (['hit', 'success', 'fail', 'miss'].includes(flag)) return true
  return Boolean(String(plan.drawResult || '').trim() || String(plan.hitDetail || '').trim())
}

function canCopyFreeNumbers(plan: ForecastPlanPayload) {
  return isFreeMode(plan) && !isPlanSettled(plan) && freeModeTokens(plan).length > 0
}

function formatCodeMode(raw?: string) {
  if (!raw) return ''
  const m = raw.toUpperCase()
  if (m.startsWith('KILL')) return '杀' + m.replace('KILL', '')
  return m
}

/** codeMode 激活位字母（剔除 KILL 前缀与 X 占位） */
function activeLetters(plan: ForecastPlanPayload): string[] {
  return String(plan.codeMode || '')
    .toUpperCase()
    .replace(/KILL|杀/g, '')
    .replace(/X/g, '')
    .split('')
    .filter(Boolean)
}

function splitIssueRange(raw?: string) {
  const value = String(raw || '').trim()
  if (!value) return { start: '', end: '' }
  const parts = value.split('-').map((s) => s.trim()).filter(Boolean)
  return { start: parts[0] || value, end: parts[1] || parts[0] || value }
}

function predictionPeriodLabel(post: PostData, plan: ForecastPlanPayload): string {
  const range = splitIssueRange(post.lotteryDrawNum)
  const start = String(plan.issueStart || '').trim() || range.start
  const end = String(plan.issueEnd || '').trim() || range.end
  if (String(post.forecastPhase || '') === '1') {
    const chase = Number(plan.chasePeriods || 0)
    const rangeText = start && end && start !== end ? `${start}-${end}` : start
    return forumDetailLabels.periodPlanRange(chase, rangeText)
  }
  const issue = start || String(post.lotteryDrawNum || '').trim()
  return issue ? forumDetailLabels.periodSingle(issue) : '--'
}

function dataTypeLabel(plan: ForecastPlanPayload): string {
  const dim = String(plan.dimension || '').trim() || getDimensionLabel(plan.planMode)
  const codeMode = formatCodeMode(plan.codeMode)
  if (dim && codeMode) return `${dim}-${codeMode}`
  return dim || codeMode || '--'
}

function selectedValueCount(plan: ForecastPlanPayload, letter: string): number {
  const raw = plan as Record<string, unknown>
  const value = String(raw[`${letter}Value`] || raw[`${letter.toLowerCase()}Value`] || '').trim()
  if (!value) return 0
  return value.split(/[\s,，;；]+/).filter(Boolean).length
}

function groupCountLabel(plan: ForecastPlanPayload): string {
  if (isFreeMode(plan)) return forumDetailLabels.groupCount(freeModeTokens(plan).length)
  const precision = String(plan.precision || '').trim()
  if (/^\d+(?:\*\d+)+$/.test(precision)) return precision
  // 按位推导 N*N（各位置选号数一致且为 6/7 时）
  const counts = activeLetters(plan)
    .map((letter) => selectedValueCount(plan, letter))
    .filter((n) => n > 0)
  if (counts.length && counts.every((n) => n === counts[0]) && (counts[0] === 6 || counts[0] === 7)) {
    return `${counts[0]}*${counts[0]}`
  }
  return precision || '--'
}

interface PlanLineToken {
  type: 'label' | 'digit'
  text: string
  hit?: boolean
}

/** 选号模式逐位行：Value / 看好 / 主攻 / 重点，命中数字高亮 */
function formatPlanLines(plan: ForecastPlanPayload): PlanLineToken[][] {
  const raw = plan as Record<string, unknown>
  const codeMode = String(plan.codeMode || '').toUpperCase()
  const isKill = codeMode.startsWith('KILL') || codeMode.startsWith('杀')
  const letters = activeLetters(plan)
  const hitDetail = parseHitDetail(plan)

  const lines: PlanLineToken[][] = []
  letters.forEach((letter) => {
    const value = String(raw[`${letter}Value`] || raw[`${letter.toLowerCase()}Value`] || '').trim()
    if (!value) return
    const drawNum = hitDetail?.positions?.[letter]?.drawNum
    const digitHit = (d: string) => drawNum != null && d === drawNum
    const digits = (text: string): PlanLineToken[] =>
      text
        .split(/[\s,]+/)
        .filter(Boolean)
        .map((d) => ({ type: 'digit', text: d, hit: digitHit(d) }))

    if (isKill) {
      lines.push([{ type: 'label', text: `${letter}：杀` }, ...digits(value)])
      return
    }
    const tokens: PlanLineToken[] = [{ type: 'label', text: `${letter}位 ` }, ...digits(value)]
    const lookGood = String(raw[`${letter}LookGood`] || raw[`${letter.toLowerCase()}LookGood`] || '').trim()
    if (lookGood) tokens.push({ type: 'label', text: ' 看好 ' }, ...digits(lookGood))
    const main = String(raw[`${letter}Main`] || raw[`${letter.toLowerCase()}Main`] || '').trim()
    if (main) tokens.push({ type: 'label', text: ' 主攻 ' }, ...digits(main))
    const point = String(raw[`${letter}Point`] || raw[`${letter.toLowerCase()}Point`] || '').trim()
    if (point) tokens.push({ type: 'label', text: ' 重点 ' }, ...digits(point))
    lines.push(tokens)
  })
  return lines
}

interface FreeModeGroup {
  label: string
  pairs: { token: string; digits: { char: string; hit: boolean }[] }[]
}

/** 自由模式大底/重点/主攻分组（命中位按 codeMode 激活位标色） */
function freeModeGroups(plan: ForecastPlanPayload): FreeModeGroup[] {
  const parsed = parseFreeModeSections(plan.summarize)
  const letters = activeLetters(plan)
  const hitDetail = parseHitDetail(plan)

  const pairsFromText = (text: string) =>
    String(text || '')
      .trim()
      .split(/[\s,，;；]+/)
      .map((s) => s.trim())
      .filter(Boolean)
      .map((token) => ({
        token,
        digits: token.split('').map((char, i) => {
          const drawNum = hitDetail?.positions?.[letters[i] || '']?.drawNum
          return { char, hit: drawNum != null && char === drawNum }
        }),
      }))

  const groups: FreeModeGroup[] = []
  const entries = [
    { key: 'base' as const, label: forumLabels.freeMode.base },
    { key: 'focus' as const, label: forumLabels.freeMode.focus },
    { key: 'main' as const, label: forumLabels.freeMode.main },
  ]
  for (const { key, label } of entries) {
    const text = parsed[key]
    if (!text.trim()) continue
    groups.push({ label: parsed.hasMarkers ? label : '', pairs: pairsFromText(text) })
  }
  if (!groups.length) {
    const pairs = pairsFromText(String(plan.diffuseValue || ''))
    if (pairs.length) groups.push({ label: '', pairs })
  }
  return groups
}

/** 正文含 HTML 时用 RichText 渲染（Web 富文本历史帖只读渲染） */
function BodyContent({ text, html }: { text: string; html?: boolean }) {
  if (!text) return null
  if (html) return <RichText className='detail-body' nodes={text} />
  return <Text className='detail-body detail-body--plain'>{text}</Text>
}

const HTML_RE = /<\/?[a-z][\s\S]*?>/i

/** 帖子详情（Web PRD §6.7.3）：作者卡 + 正文卡 + 开奖区 + 预测方案卡 + 评论区 + 吸底操作栏 */
export default function ForumDetailPage() {
  const params = Taro.getCurrentInstance().router?.params || {}
  const postType: PostType = params.type === 'prediction' ? 'prediction' : 'exchange'
  const postId = params.id || ''
  const partition = params.partition || 'all'

  const { profile } = useAuth()
  const [post, setPost] = useState<PostData | null>(null)
  const [loading, setLoading] = useState(true)
  const [notFound, setNotFound] = useState(false)
  const [menuVisible, setMenuVisible] = useState(false)
  const [authorInfo, setAuthorInfo] = useState<UserPublicInfo | null>(null)
  const [isFollowed, setIsFollowed] = useState(false)

  const loadDetail = useCallback(async () => {
    setLoading(true)
    setNotFound(false)
    try {
      const res = postType === 'exchange' ? await fetchForumDetail(postId) : await fetchPredictionDetail(postId)
      if (!res || !res.id) {
        setPost(null)
        setNotFound(true)
      } else {
        setPost(res as PostData)
      }
    } catch {
      setPost(null)
      setNotFound(true)
    } finally {
      setLoading(false)
    }
  }, [postType, postId])

  useEffect(() => {
    loadDetail()
  }, [loadDetail])

  const authorUserId = authorIdOf(post)

  useEffect(() => {
    setAuthorInfo(null)
    setIsFollowed(false)
    if (!authorUserId) return
    fetchUserInfo(authorUserId)
      .then((info) => setAuthorInfo(info))
      .catch(() => setAuthorInfo(null))
    if (profile?.id) {
      fetchIsFollowing(authorUserId)
        .then((res) => setIsFollowed(Boolean(res?.followed)))
        .catch(() => {})
    }
  }, [authorUserId, profile?.id])

  const plans = useMemo(() => (Array.isArray(post?.planVOList) ? post!.planVOList! : []), [post])

  const isMine = useMemo(() => {
    const uid = Number(profile?.id || 0)
    return uid > 0 && authorUserId != null && uid === authorUserId
  }, [profile, authorUserId])

  // 「本期开奖」区：首个 plan 的 hitDetail.positions.{A-G}.drawNum
  const drawBalls = useMemo(() => {
    for (const plan of plans) {
      const hd = parseHitDetail(plan)
      const nums = POSITION_LETTERS.map((p) => hd?.positions?.[p]?.drawNum).filter(Boolean)
      if (nums.length) return nums as string[]
    }
    return [] as string[]
  }, [plans])

  const hasAnyHit = useMemo(
    () =>
      plans.some((plan) => {
        const overall = parseHitDetail(plan)?.overall
        return resolveHitStatus(plan.hitFlag, overall) === 'hit'
      }),
    [plans],
  )

  const copyablePlans = useMemo(() => plans.filter((p) => canCopyFreeNumbers(p)), [plans])

  // 正文：交流帖渲染 content；预测帖渲染 summarize 的【数据总结】段
  const bodyText = useMemo(() => {
    if (!post) return ''
    if (postType === 'exchange') return String(post.content || '')
    return extractSummarySection(plans[0]?.summarize)
  }, [post, postType, plans])

  const detailPath = `/pages/forum-detail/index?partition=${partition}&type=${postType}&id=${postId}`
  const postTitle = post?.title?.trim() || forumDetailLabels.noTitle

  const copyText = useCallback((data: string, tip: string) => {
    Taro.setClipboardData({
      data,
      success: () => Taro.showToast({ title: tip, icon: 'none' }),
      fail: () => Taro.showToast({ title: forumDetailLabels.copyFailed, icon: 'none' }),
    })
  }, [])

  /** 「···」菜单：复制号码（仅未结算自由模式） */
  const copyAllNumbers = useCallback(() => {
    const texts = copyablePlans
      .map((plan) => buildFreeModeCopyText(plan.summarize, plan.diffuseValue))
      .filter(Boolean)
    if (!texts.length) {
      Taro.showToast({ title: forumDetailLabels.noCopyableNumbers, icon: 'none' })
      return
    }
    copyText(texts.join('\n'), forumDetailLabels.numbersCopied)
  }, [copyablePlans, copyText])

  const sharePost = useCallback(() => {
    copyText(`${postTitle}\n${detailPath}`, forumDetailLabels.shareCopied)
  }, [postTitle, detailPath, copyText])

  const copyPlanNumbers = useCallback(
    (plan: ForecastPlanPayload) => {
      const text = buildFreeModeCopyText(plan.summarize, plan.diffuseValue)
      if (!text) {
        Taro.showToast({ title: forumDetailLabels.noCopyableNumbers, icon: 'none' })
        return
      }
      copyText(text, forumDetailLabels.numbersCopied)
    },
    [copyText],
  )

  const goEdit = useCallback(() => {
    Taro.navigateTo({ url: `/pages/publish/index?type=${postType}&mode=edit&id=${postId}&partition=${partition}` })
  }, [postType, postId, partition])

  const menuItems = useMemo(() => {
    const items: { key: string; label: string; onTap: () => void }[] = []
    if (copyablePlans.length) items.push({ key: 'copy', label: forumDetailLabels.copyNumbers, onTap: copyAllNumbers })
    if (isMine) items.push({ key: 'edit', label: forumDetailLabels.editPost, onTap: goEdit })
    items.push({ key: 'share', label: forumDetailLabels.sharePost, onTap: sharePost })
    return items
  }, [copyablePlans, isMine, copyAllNumbers, goEdit, sharePost])

  if (loading) {
    return (
      <View className='detail-page'>
        <Skeleton rows={5} />
      </View>
    )
  }

  if (notFound || !post) {
    return (
      <View className='detail-page'>
        <Empty text={forumDetailLabels.notFound} />
      </View>
    )
  }

  const authorName =
    authorInfo?.nickname || post.username || post.nickname || forumDetailLabels.anonymous
  const authorAvatar = authorInfo?.avatar || post.userAvatar
  const lotteryCode = post.lotteryCode
  const dimLabel = postType === 'prediction' ? dataTypeLabel(plans[0] || {}) : ''
  const isPlanPhase = String(post.forecastPhase || '') === '1'

  return (
    <View className='detail-page'>
      {/* 正文卡：作者卡吸顶于卡顶部（单列布局） */}
      <View className='post-card'>
        <View className='author-row' onClick={() => authorUserId && goExpert(authorUserId)}>
          <Avatar src={authorAvatar} name={authorName} size={44} />
          <View className='author-row__info'>
            <Text className='author-row__name'>{authorName}</Text>
            <Text className='author-row__role'>
              {authorInfo?.identity === 'T' ? forumDetailLabels.roleExpert : forumDetailLabels.roleUser}
            </Text>
          </View>
          {authorUserId ? (
            <View onClick={(e) => e.stopPropagation()}>
              <FollowButton userId={authorUserId} isFollowed={isFollowed} onChange={setIsFollowed} />
            </View>
          ) : null}
          <View
            className='post-card__more'
            onClick={(e) => {
              e.stopPropagation()
              setMenuVisible(true)
            }}
          >
            <Text className='post-card__more-text'>···</Text>
          </View>
        </View>

        {/* meta 行 */}
        <View className='post-meta'>
          <Text className={`post-tag ${postType === 'exchange' ? 'post-tag--exchange' : 'post-tag--prediction'}`}>
            {postType === 'exchange' ? forumLabels.exchangeTag : forumLabels.predictionTag}
          </Text>
          {dimLabel ? <Text className='post-tag post-tag--dim'>{dimLabel}</Text> : null}
          {lotteryCode ? <LotteryTag code={lotteryCode} /> : null}
          {postType === 'prediction' && post.lotteryDrawNum ? (
            <Text className='post-meta__issue'>{forumDetailLabels.issueLabel(post.lotteryDrawNum)}</Text>
          ) : null}
          <Text className='post-meta__time'>{formatTime(post.createTime)}</Text>
        </View>

        <Text className='post-title'>{postTitle}</Text>

        {/* 预测帖「本期开奖」区 */}
        {postType === 'prediction' && drawBalls.length > 0 ? (
          <View className='draw-section'>
            <Text className='draw-section__label'>{forumDetailLabels.drawSectionTitle}</Text>
            <NumberBalls numbers={drawBalls} size='small' />
            {hasAnyHit ? <Text className='draw-section__hit'>{forumLabels.hitBadge}</Text> : null}
          </View>
        ) : null}

        {/* 预测方案卡 */}
        {postType === 'prediction' && plans.length > 0 ? (
          <View className='plans-section'>
            <Text className='section-title'>{forumDetailLabels.plansTitle}</Text>
            {plans.map((plan, idx) => {
              const hitStatus = resolveHitStatus(plan.hitFlag, parseHitDetail(plan)?.overall)
              return (
                <View
                  key={String(plan.id ?? idx)}
                  className={`plan-card${hitStatus === 'hit' ? ' plan-card--hit' : ''}${hitStatus === 'miss' ? ' plan-card--miss' : ''}`}
                >
                  <View className='plan-card__header'>
                    <View className='plan-card__info'>
                      <Text className='plan-card__title'>
                        {isPlanPhase ? forumDetailLabels.planPhasePlan : forumDetailLabels.planPhaseSingle}
                      </Text>
                      <View className='plan-card__meta-row'>
                        <Text className='plan-card__meta-item'>
                          {forumDetailLabels.periodLabel}：{predictionPeriodLabel(post, plan)}
                        </Text>
                        <Text className='plan-card__meta-item'>
                          {forumDetailLabels.dataTypeLabel}：{dataTypeLabel(plan)}
                        </Text>
                        <Text className='plan-card__meta-item'>
                          {forumDetailLabels.groupCountLabel}：{groupCountLabel(plan)}
                        </Text>
                      </View>
                    </View>
                    <View className='plan-card__badges'>
                      {canCopyFreeNumbers(plan) ? (
                        <Text className='plan-card__copy' onClick={() => copyPlanNumbers(plan)}>
                          {forumDetailLabels.copyPlan}
                        </Text>
                      ) : null}
                      <HitBadge hitFlag={plan.hitFlag} hitDetail={plan.hitDetail} />
                    </View>
                  </View>

                  {isFreeMode(plan) ? (
                    <View className='plan-card__data-list'>
                      {freeModeGroups(plan).map((group, gi) => (
                        <View key={gi} className='plan-card__data'>
                          {group.label ? <Text className='plan-card__data-head'>{group.label}</Text> : null}
                          <View className='plan-card__data-body'>
                            {group.pairs.map((pair, pi) => (
                              <View key={pi} className='free-pair'>
                                {pair.digits.map((d, di) => (
                                  <Text key={di} className={`plan-digit${d.hit ? ' plan-digit--hit' : ''}`}>
                                    {d.char}
                                  </Text>
                                ))}
                              </View>
                            ))}
                          </View>
                        </View>
                      ))}
                    </View>
                  ) : (
                    <View className='plan-card__lines'>
                      {formatPlanLines(plan).map((line, li) => (
                        <View key={li} className='plan-card__line'>
                          {line.map((token, ti) =>
                            token.type === 'digit' ? (
                              <Text key={ti} className={`plan-digit${token.hit ? ' plan-digit--hit' : ''}`}>
                                {token.text}
                              </Text>
                            ) : (
                              <Text key={ti} className='plan-label'>
                                {token.text}
                              </Text>
                            ),
                          )}
                        </View>
                      ))}
                    </View>
                  )}
                </View>
              )
            })}
          </View>
        ) : null}

        {/* 正文 */}
        {bodyText ? (
          <View className='content-section'>
            <BodyContent text={bodyText} html={HTML_RE.test(bodyText)} />
          </View>
        ) : null}
      </View>

      {/* 评论区（双 adapter 能力开关，Web PRD §6.7.4） */}
      <CommentSection
        sourceId={postId}
        adapter={postType === 'exchange' ? forumCommentAdapter : predictionCommentAdapter}
        capabilities={
          postType === 'exchange'
            ? { edit: true, delete: true, paginated: true }
            : { edit: false, delete: false, paginated: false }
        }
        actions={
          <>
            <View className='bar-action' onClick={() => Taro.showToast({ title: forumDetailLabels.collectComingSoon, icon: 'none' })}>
              <Text className='bar-action__text'>
                {forumDetailLabels.collect}
                {Number(post.collectNum || 0) > 0 ? ` ${post.collectNum}` : ''}
              </Text>
            </View>
            <View className='bar-action' onClick={sharePost}>
              <Text className='bar-action__text'>{commonLabels.share}</Text>
            </View>
          </>
        }
      />

      {/* 「···」底部动作菜单 */}
      <Popup visible={menuVisible} position='bottom' round destroyOnClose onClose={() => setMenuVisible(false)}>
        <View className='sheet'>
          <Text className='sheet__title'>{forumDetailLabels.menuTitle}</Text>
          {menuItems.map((item) => (
            <View
              key={item.key}
              className='sheet__action'
              onClick={() => {
                setMenuVisible(false)
                item.onTap()
              }}
            >
              <Text className='sheet__action-text'>{item.label}</Text>
            </View>
          ))}
          <View className='sheet__cancel' onClick={() => setMenuVisible(false)}>
            <Text className='sheet__cancel-text'>{commonLabels.cancel}</Text>
          </View>
        </View>
      </Popup>
    </View>
  )
}
