import { ScrollView, View, Text } from '@tarojs/components'
import './index.css'

interface PlanTabsProps {
  count: number
  active: number
  max: number
  labelOf: (index: number) => string
  addLabel: string
  onSwitch: (index: number) => void
  onAdd: () => void
  /** 长按分段触发删除（父组件负责确认弹窗） */
  onRemove: (index: number) => void
}

/** 方案分段选择器：横向滑动，末尾「+」新增，长按删除（产品方案 §6.6） */
export default function PlanTabs({ count, active, max, labelOf, addLabel, onSwitch, onAdd, onRemove }: PlanTabsProps) {
  return (
    <ScrollView scrollX enhanced showScrollbar={false} className='plan-tabs'>
      <View className='plan-tabs__inner'>
        {Array.from({ length: count }).map((_, idx) => (
          <View
            key={idx}
            className={`plan-tabs__item${active === idx ? ' plan-tabs__item--active' : ''}`}
            onClick={() => onSwitch(idx)}
            onLongPress={() => onRemove(idx)}
          >
            <Text className={`plan-tabs__text${active === idx ? ' plan-tabs__text--active' : ''}`}>{labelOf(idx)}</Text>
          </View>
        ))}
        {count < max ? (
          <View className='plan-tabs__item plan-tabs__item--add' onClick={onAdd}>
            <Text className='plan-tabs__text plan-tabs__text--add'>+ {addLabel}</Text>
          </View>
        ) : null}
      </View>
    </ScrollView>
  )
}
