import { View, Text } from '@tarojs/components'
import { commonLabels } from '@/labels'
import './index.css'

interface EmptyProps {
  text?: string
  actionText?: string
  onAction?: () => void
}

/** 统一空态：文案 + 可选主操作按钮（产品方案 §3.5） */
export default function Empty({ text = commonLabels.empty, actionText, onAction }: EmptyProps) {
  return (
    <View className='empty'>
      <Text className='empty__icon'>📭</Text>
      <Text className='empty__text'>{text}</Text>
      {actionText && onAction ? (
        <View className='empty__action' onClick={onAction}>
          <Text className='empty__action-text'>{actionText}</Text>
        </View>
      ) : null}
    </View>
  )
}
