.plan-tabs {
  width: 100%;
  white-space: nowrap;
}

.plan-tabs__inner {
  display: inline-flex;
  flex-direction: row;
  gap: 8px;
  padding: 4px 0;
}

.plan-tabs__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 72px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  border: 1px solid var(--color-border);
}

.plan-tabs__item--active {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

.plan-tabs__item--add {
  border-style: dashed;
}

.plan-tabs__text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.plan-tabs__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.plan-tabs__text--add {
  color: var(--color-primary);
}
