import { Image, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import logo from '@/assets/app-icon/apple-touch-icon.png'
import iconNotice from '@/assets/navbar/notice.png'
import './index.css'

interface NavBarProps {
  title: string
  /** 滚动渐变：0 全透明 → 1 不透明；不传则恒不透明（现状） */
  fadeOpacity?: number
  /** 覆盖模式：absolute 悬浮于内容之上（RN 页面内滚动场景替代不支持的 sticky），默认 sticky 吸顶 */
  overlay?: boolean
}

/**
 * RN 端顶部安全区：CSS 的 env(safe-area-inset-top) 会被 postcss-rn-calc 剥离，
 * 需运行时从系统信息取状态栏高度（taro-rn 内部走 react-native-safe-area-context 的
 * initialWindowMetrics，iOS 灵动岛机型约 59pt）。H5 端由 CSS env() 处理，返回 0。
 */
function getStatusBarHeight(): number {
  if (process.env.TARO_ENV !== 'rn') return 0
  try {
    return Taro.getSystemInfoSync().statusBarHeight || 0
  } catch {
    return 0
  }
}

/** RN 端状态栏高度（H5 恒为 0，顶部安全区由 CSS env() 处理）。导出供需要预留 NavBar 占位的页面使用（如首页无轮播图时） */
export const STATUS_BAR_HEIGHT = getStatusBarHeight()

/** 自定义顶部导航栏（一级 Tab 页，页面 config 需 navigationStyle: 'custom'）：左侧 App logo + 标题，右侧通知中心入口 */
export default function NavBar({ title, fadeOpacity, overlay }: NavBarProps) {
  const fading = fadeOpacity !== undefined
  const opacity = fading ? Math.min(1, Math.max(0, fadeOpacity)) : 1
  const className = [
    'nav-bar',
    overlay ? 'nav-bar--overlay' : '',
    // 渐变未到底时去掉投影，避免透明底色上悬浮阴影
    fading && opacity < 1 ? 'nav-bar--flat' : '',
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <View
      className={className}
      style={{
        paddingTop: STATUS_BAR_HEIGHT || undefined,
        // 渐变色值对齐 token --color-bg-card（#ffffff）
        backgroundColor: fading ? `rgba(255, 255, 255, ${opacity})` : undefined,
      }}
    >
      <View className='nav-bar__inner' style={fading ? { opacity } : undefined}>
        <View className='nav-bar__brand'>
          <Image className='nav-bar__logo' src={logo} />
          <Text className='nav-bar__title'>{title}</Text>
        </View>
        {/* 通知中心入口（功能暂未实现） */}
        <Image className='nav-bar__notice' src={iconNotice} />
      </View>
    </View>
  )
}
