.comment-item {
  display: flex;
  flex-direction: row;
}

.comment-item__body {
  flex: 1;
  min-width: 0;
  margin-left: 10px;
}

.comment-item__meta {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  flex-wrap: wrap;
}

.comment-item__nickname {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
}

.comment-item__reply-to {
  margin-left: 6px;
  font-size: 12px;
  color: var(--color-primary);
}

.comment-item__time {
  margin-left: 8px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.comment-item__content {
  display: block;
  margin: 4px 0 2px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text);
  white-space: pre-wrap;
  word-break: break-word;
}

.comment-item__actions {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
}

.comment-item__action {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-right: 20px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.comment-item__action--active {
  color: var(--color-primary);
  font-weight: 600;
}

.comment-item__action--danger {
  color: var(--color-danger);
}
