.profile-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

/* 未登录引导空态 */
.guest {
  margin: 16px;
  padding: 48px 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.guest__title {
  margin-top: 16px;
  font-size: 17px;
  font-weight: 600;
}

.guest__desc {
  margin-top: 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
  text-align: center;
}

.guest__btn {
  margin-top: 24px;
  min-height: 48px;
  padding: 0 40px;
  border-radius: 999px;
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.guest__btn-text {
  color: #fff;
  font-size: 15px;
}

/* Hero 卡 */
.hero {
  margin: 16px;
  padding: 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.hero__main {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.hero__avatar {
  flex-shrink: 0;
  min-width: 64px;
  min-height: 64px;
}

.hero__info {
  flex: 1;
  margin-left: 16px;
  display: flex;
  flex-direction: column;
}

.hero__nickname {
  font-size: 18px;
  font-weight: 700;
}

.hero__member {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.hero__avatar-hint {
  margin-top: 4px;
  font-size: 11px;
  color: var(--color-text-placeholder);
}

.hero__edit {
  flex-shrink: 0;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__edit-text {
  font-size: 13px;
  color: var(--color-text);
}

.hero__integral {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
  display: flex;
  flex-direction: row;
  align-items: center;
}

.hero__integral-label {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.hero__integral-value {
  flex: 1;
  margin-left: 8px;
  font-size: 18px;
  font-weight: 700;
  color: var(--color-primary);
}

.hero__recharge {
  min-height: 44px;
  padding: 0 20px;
  border-radius: 999px;
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__recharge-text {
  color: #fff;
  font-size: 13px;
}

.stats {
  margin-top: 20px;
  display: flex;
  flex-direction: row;
}

.stats__item {
  flex: 1;
  min-height: 44px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.stats__value {
  font-size: 18px;
  font-weight: 700;
}

.stats__label {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 通用面板 */
.panel {
  margin: 0 16px 12px;
  padding: 20px 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.panel__head {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
}

.panel__title {
  font-size: 16px;
  font-weight: 600;
}

.panel__subtitle {
  display: block;
  margin: 16px 0 8px;
  font-size: 13px;
  color: var(--color-text-secondary);
}

.panel__more {
  min-height: 44px;
  display: flex;
  align-items: center;
  font-size: 13px;
  color: var(--color-primary);
}

/* 命中率概览 */
.rate-hero {
  margin-top: 12px;
  display: flex;
  flex-direction: row;
  align-items: center;
}

.rate-hero__value {
  font-size: 32px;
  font-weight: 700;
  color: var(--color-primary);
}

.rate-hero__meta {
  margin-left: 16px;
  display: flex;
  flex-direction: column;
}

.rate-hero__label {
  font-size: 13px;
  color: var(--color-text);
}

.rate-hero__stat {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.rate-meta {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 趋势简图（纯 View 横向柱状条，不引入图表库） */
.trend__row {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 8px;
}

.trend__label {
  width: 72px;
  font-size: 11px;
  color: var(--color-text-secondary);
}

.trend__track {
  flex: 1;
  height: 8px;
  border-radius: 999px;
  background: var(--color-bg);
  overflow: hidden;
}

.trend__bar {
  height: 100%;
  border-radius: 999px;
  background: var(--color-primary);
}

.trend__value {
  width: 44px;
  text-align: right;
  font-size: 11px;
  color: var(--color-text-secondary);
}

/* modeSummaries chips */
.chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-size: 12px;
}

/* 最新预测卡片 */
.forecast-card {
  margin-top: 12px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.forecast-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 44px;
}

.forecast-card__issue {
  font-size: 13px;
  color: var(--color-text);
}

.forecast-card__phase {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.forecast-card__title {
  display: block;
  margin-top: 8px;
  font-size: 15px;
  font-weight: 600;
}

.forecast-card__plans {
  margin-top: 8px;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.plan-tag {
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  font-size: 11px;
  color: var(--color-text-secondary);
}

.forecast-card__foot {
  margin-top: 8px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
}

.forecast-card__time,
.forecast-card__meta {
  font-size: 12px;
  color: var(--color-text-secondary);
}

/* 功能列表 */
.menu {
  margin: 0 16px 12px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.menu__item {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  min-height: 56px;
  padding: 0 24px;
  border-bottom: 1px solid var(--color-border);
}

.menu__item--last {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.menu__label {
  font-size: 15px;
  color: var(--color-text);
}

.menu__arrow {
  font-size: 16px;
  color: var(--color-text-placeholder);
}

/* 退出登录 */
.logout {
  margin: 24px 16px 0;
  min-height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logout__text {
  font-size: 15px;
  color: var(--color-danger);
}

/* 弹层内容 */
.sheet {
  padding: 24px;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.sheet__title {
  display: block;
  margin-bottom: 20px;
  text-align: center;
  font-size: 17px;
  font-weight: 600;
}

.sheet__content {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-secondary);
}

.sheet__row {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  min-height: 56px;
  border-bottom: 1px solid var(--color-border);
}

.sheet__row--last {
  border-bottom-width: 0; /* RN 端不支持 border-bottom: none */
}

.sheet__row-info {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.sheet__row-label {
  font-size: 15px;
  color: var(--color-text);
}

.sheet__row-hint {
  margin-top: 4px;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

/* 编辑资料表单 */
.form__item {
  margin-bottom: 16px;
}

.form__label {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  color: var(--color-text-secondary);
}
