.tools-page {
  min-height: 100vh;
  padding: 16px 16px var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.tools-grid {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 12px;
}

.tool-card {
  position: relative;
  width: var(--tools-item-width, calc(50% - 6px));
  padding: 20px 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.tool-card__badge {
  position: absolute;
  top: 0;
  right: 0;
  padding: 4px 10px;
  border-radius: 0 var(--radius-md) 0 var(--radius-md);
  background: var(--color-warning);
  font-size: 11px;
  color: #fff;
}

.tool-card__badge--free {
  background: var(--color-success);
}

.tool-card__name {
  display: block;
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text);
}

.tool-card__desc {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}
