import { Text, View } from '@tarojs/components'
import {
  BOARD_COLORS,
  isRearDigitColumn,
  isSectionEndRow,
  splitAfterIndexOf,
  type BoardGeometry,
  type BoardRow,
} from './model'

interface DrawBoardProps {
  rows: BoardRow[]
  geometry: BoardGeometry
  lotteryCode: string
  drawCount: number
}

/**
 * 奖表 UI（期号 | 合值 | 数字格），View/Text 网格，双端共享。
 * 尺寸全部内联（RN 无 CSS 变量运行时），配色与 canvas/svg 导出统一走 BOARD_COLORS。
 */
export default function DrawBoard({ rows, geometry, lotteryCode, drawCount }: DrawBoardProps) {
  const splitAfter = splitAfterIndexOf(lotteryCode)
  return (
    <View className='draw-board' style={{ width: geometry.boardWidth, height: geometry.boardHeight }}>
      {rows.map((row, rowIndex) => {
        const sectionEnd = isSectionEndRow(rowIndex)
        const rowBorderColor = sectionEnd ? BOARD_COLORS.sectionBorder : BOARD_COLORS.border
        return (
          <View
            key={row.key}
            className='draw-board__row'
            style={{
              height: geometry.rowHeight,
              borderBottomWidth: sectionEnd ? 3 : 1,
              borderBottomColor: rowBorderColor,
            }}
          >
            <View
              className='draw-board__issue'
              style={{ width: geometry.issueColumnWidth, height: geometry.rowHeight }}
            >
              {!row.placeholder && row.issue ? (
                <Text
                  className='draw-board__issue-num'
                  numberOfLines={1}
                  style={{ fontSize: geometry.issueFontSize }}
                >
                  {row.issue}
                </Text>
              ) : null}
              {!row.placeholder && row.weekLabel ? (
                <Text
                  className='draw-board__issue-week'
                  numberOfLines={1}
                  style={{ fontSize: geometry.issueWeekFontSize }}
                >
                  {row.weekLabel}
                </Text>
              ) : null}
            </View>
            <View
              className='draw-board__sum'
              style={{ width: geometry.sumColumnWidth, height: geometry.rowHeight }}
            >
              {!row.placeholder && row.sumText ? (
                <Text
                  className='draw-board__sum-text'
                  numberOfLines={1}
                  style={{ fontSize: geometry.sumFontSize }}
                >
                  {row.sumText}
                </Text>
              ) : null}
            </View>
            {Array.from({ length: drawCount }, (_, columnIndex) => {
              const value = row.numbers[columnIndex] || ''
              const rear = isRearDigitColumn(lotteryCode, columnIndex)
              const isSplit = columnIndex === splitAfter
              return (
                <View
                  key={columnIndex}
                  className='draw-board__digit'
                  style={{
                    width: geometry.digitCellWidth,
                    height: geometry.rowHeight,
                    backgroundColor: value ? BOARD_COLORS.digitHitBackground : BOARD_COLORS.digitBackground,
                    borderRightWidth: isSplit ? 3 : 1,
                    borderRightColor: isSplit ? BOARD_COLORS.splitBorder : BOARD_COLORS.border,
                  }}
                >
                  {value ? (
                    <Text
                      className='draw-board__digit-text'
                      numberOfLines={1}
                      style={{ fontSize: rear ? geometry.rearDigitFontSize : geometry.digitFontSize }}
                    >
                      {value}
                    </Text>
                  ) : null}
                </View>
              )
            })}
          </View>
        )
      })}
    </View>
  )
}
