:root,
page {
  --nut-scale-f: 1;
  --nut-scale-font: var(--nut-scale-f, 1);
  --nut-scale-icon: var(--nut-scale-f, 1);
  --nut-icon-height: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
  --nut-icon-width: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
  --nut-icon-line-height: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
}

.nut-overlay {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  width: 100%;
  height: 100%;
  background-color: var(--nutui-overlay-bg-color, var(--nutui-color-mask, rgba(0, 0, 0, 0.7)));
}

.nut-overflow-hidden {
  overflow: hidden !important;
}

@keyframes nut-fade-in {
  0% {
    opacity: 0;
  }
  1% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
@keyframes nut-fade-out {
  0% {
    opacity: 1;
  }
  1% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}
.nut-overlay-slide-enter-active, .nut-overlay-slide-appear-active {
  animation-fill-mode: both;
  animation-name: nut-fade-in;
  animation-duration: var(--nutui-overlay-animation-duration, 0.3s);
}
.nut-overlay-slide-exit-active {
  animation-fill-mode: both;
  animation-name: nut-fade-out;
  animation-duration: var(--nutui-overlay-animation-duration, 0.3s);
}

[dir=rtl] .nut-overlay,
.nut-rtl .nut-overlay {
  left: auto;
  right: 0;
}