import { useState } from 'react'
import { View, Text, Input } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { useAuth } from '@/store/auth'
import { authLabels } from '@/labels/auth'
import { TAB_PAGES } from '@/utils/nav'
import './index.css'

/** 注册成功（自动登录）后的站内回跳：仅接受站内路径，Tab 页用 switchTab */
function navigateAfterAuth(raw?: string | null) {
  const target = String(raw || '').trim()
  const safe = target.startsWith('/') ? target : '/pages/profile/index'
  const path = safe.split('?')[0]
  if (TAB_PAGES.includes(path)) {
    Taro.switchTab({ url: path })
  } else {
    Taro.redirectTo({ url: safe })
  }
}

/** 全屏模态注册页（产品方案 §6.11）：邀请码支持 ?inviCode= / ?invite= 预填 */
export default function RegisterPage() {
  const { register } = useAuth()
  const params = Taro.getCurrentInstance().router?.params
  const redirect = params?.redirect
  const [account, setAccount] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [inviCode, setInviCode] = useState(String(params?.inviCode || params?.invite || ''))
  const [showPassword, setShowPassword] = useState(false)
  const [agreed, setAgreed] = useState(false)
  const [submitting, setSubmitting] = useState(false)

  const closeModal = () => {
    if (Taro.getCurrentPages().length > 1) {
      Taro.navigateBack()
    } else {
      Taro.switchTab({ url: '/pages/home/index' })
    }
  }

  const submit = async () => {
    if (submitting) return
    if (!account.trim()) {
      Taro.showToast({ title: authLabels.errors.accountRequired, icon: 'none' })
      return
    }
    if (!password) {
      Taro.showToast({ title: authLabels.errors.passwordRequired, icon: 'none' })
      return
    }
    if (!confirmPassword) {
      Taro.showToast({ title: authLabels.errors.confirmRequired, icon: 'none' })
      return
    }
    if (password !== confirmPassword) {
      Taro.showToast({ title: authLabels.errors.passwordMismatch, icon: 'none' })
      return
    }
    if (!agreed) {
      Taro.showToast({ title: authLabels.errors.termsRequired, icon: 'none' })
      return
    }
    setSubmitting(true)
    try {
      await register({
        account: account.trim(),
        passwd: password,
        confirmPasswd: confirmPassword,
        inviCode: inviCode.trim() || undefined,
      })
      navigateAfterAuth(redirect)
    } catch (err: any) {
      Taro.showToast({ title: err?.message || authLabels.errors.registerFailed, icon: 'none' })
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <View className='auth-page'>
      <View className='auth-page__close' onClick={closeModal}>
        <Text className='auth-page__close-icon'>✕</Text>
      </View>

      <Text className='auth-page__title'>{authLabels.register.title}</Text>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={account}
          placeholder={authLabels.register.accountPlaceholder}
          onInput={(e) => setAccount(e.detail.value)}
        />
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={password}
          password={!showPassword}
          placeholder={authLabels.register.passwordPlaceholder}
          onInput={(e) => setPassword(e.detail.value)}
        />
        <Text className='auth-field__toggle' onClick={() => setShowPassword(!showPassword)}>
          {showPassword ? authLabels.hidePassword : authLabels.showPassword}
        </Text>
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={confirmPassword}
          password={!showPassword}
          placeholder={authLabels.register.confirmPlaceholder}
          onInput={(e) => setConfirmPassword(e.detail.value)}
        />
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={inviCode}
          placeholder={authLabels.register.inviCodePlaceholder}
          onInput={(e) => setInviCode(e.detail.value)}
        />
      </View>

      <View className='checkbox' onClick={() => setAgreed(!agreed)}>
        <View className={`checkbox__box${agreed ? ' checkbox__box--checked' : ''}`}>
          {agreed ? <Text className='checkbox__tick'>✓</Text> : null}
        </View>
        <Text className='checkbox__label'>{authLabels.register.agreeTerms}</Text>
      </View>

      <View className={`auth-submit${submitting ? ' auth-submit--disabled' : ''}`} onClick={submit}>
        <Text className='auth-submit__text'>
          {submitting ? authLabels.register.submitting : authLabels.register.submit}
        </Text>
      </View>
    </View>
  )
}
