.skeleton {
  padding: 16px;
}

.skeleton__card {
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  padding: 24px;
  margin-bottom: 16px;
}

.skeleton__plain {
  padding: 16px 0;
}

.skeleton__line {
  height: 24px;
  border-radius: 6px;
  background-color: #e8eaee; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(90deg, #eef0f3 25%, #e2e5ea 50%, #eef0f3 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.2s infinite;
  margin-bottom: 16px;
}

.skeleton__line--title {
  width: 60%;
  height: 30px;
}

.skeleton__line--short {
  width: 35%;
  margin-bottom: 0;
}

@keyframes skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
