import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro, { usePullDownRefresh } from '@tarojs/taro'
import Popup from '@nutui/nutui-react-taro/dist/es/packages/popup'
import '@nutui/nutui-react-taro/dist/es/packages/popup/style/css'
import { getDimensionLabel } from '@/constants/lottery'
import { getPrecisionOptions, type DimensionCode } from '@/constants/forecast'
import { fetchExpertHistory, fetchExpertRank, fetchIsFollowing, fetchUserInfo } from '@/services/api'
import { useAuth } from '@/store/auth'
import { goExpertPosts } from '@/utils/nav'
import { EXPERT_CHASE_OPTIONS, EXPERT_HISTORY_ROUNDS_OPTIONS, expertLabels } from '@/labels/rank'
import { commonLabels } from '@/labels'
import type { Expert, ExpertPlanCycle, UserPublicInfo } from '@/types'
import Avatar from '@/components/Avatar'
import FollowButton from '@/components/FollowButton'
import Skeleton from '@/components/Skeleton'
import Empty from '@/components/Empty'
import './index.css'

type HistoryMode = 'single' | 'plan'

/** 成绩 miss 判定（对齐 Web expert 详情：miss/x/failed 视为未中） */
function isMissResult(resultLabel?: string) {
  return /miss|x|failed/i.test(String(resultLabel || ''))
}

/** 达人详情（Web PRD §6.5，裁剪：不做「本期推荐锁定区」、移除私信按钮） */
export default function ExpertPage() {
  const { isLoggedIn } = useAuth()
  const expertId = Number(Taro.getCurrentInstance().router?.params?.id) || 1

  const [rankExpert, setRankExpert] = useState<Expert | null>(null)
  const [userInfo, setUserInfo] = useState<UserPublicInfo | null>(null)
  const [profileLoading, setProfileLoading] = useState(true)
  const [followed, setFollowed] = useState(false)

  // 历史成绩筛选
  const [rounds, setRounds] = useState<number>(10)
  const [mode, setMode] = useState<HistoryMode>('plan')
  const [dimension, setDimension] = useState('')
  const [precision, setPrecision] = useState('')
  const [chasePeriods, setChasePeriods] = useState('')
  const [availableModes, setAvailableModes] = useState<HistoryMode[]>(['single', 'plan'])
  const [cycles, setCycles] = useState<ExpertPlanCycle[]>([])
  const [historyLoading, setHistoryLoading] = useState(true)
  const [historyError, setHistoryError] = useState('')
  const [expandedIds, setExpandedIds] = useState<Record<string, boolean>>({})
  const [panelVisible, setPanelVisible] = useState(false)
  const historySeqRef = useRef(0)

  /** 资料卡数据：fetchExpertRank 全量中找当前 id，fetchUserInfo 兜底昵称/头像/计数 */
  const loadProfile = useCallback(async () => {
    setProfileLoading(true)
    const [rankResult, infoResult] = await Promise.allSettled([fetchExpertRank({}), fetchUserInfo(expertId)])
    const list = rankResult.status === 'fulfilled' ? rankResult.value || [] : []
    setRankExpert(list.find((item) => Number(item.id) === expertId) || null)
    setUserInfo(infoResult.status === 'fulfilled' ? infoResult.value : null)
    setProfileLoading(false)
  }, [expertId])

  // 登录后补关注态（静默失败忽略）
  useEffect(() => {
    if (!isLoggedIn) return
    fetchIsFollowing(expertId)
      .then((res) => {
        if (typeof res?.followed === 'boolean') setFollowed(res.followed)
      })
      .catch(() => {})
  }, [isLoggedIn, expertId])

  const display = useMemo(() => {
    const nickname = rankExpert?.nickName || userInfo?.nickname || expertLabels.fallbackName
    return {
      id: rankExpert?.id || userInfo?.id || expertId,
      nickname,
      avatar: rankExpert?.avatar || userInfo?.avatar || '',
      isVerified: rankExpert?.isVerified ?? userInfo?.identity === 'T',
      winRate: rankExpert?.winRate ?? 0,
      consecutiveWins: rankExpert?.consecutiveWins ?? 0,
      rating: rankExpert?.rating ?? 0,
    }
  }, [rankExpert, userInfo, expertId])

  // 初始关注态：排行榜 / 用户公开信息
  useEffect(() => {
    setFollowed(!!rankExpert?.isFollowed || !!userInfo?.isFollowing)
  }, [rankExpert, userInfo])

  // 昵称就绪后动态更新导航栏标题
  useEffect(() => {
    if (display.nickname && display.nickname !== expertLabels.fallbackName) {
      Taro.setNavigationBarTitle({ title: expertLabels.navTitle(display.nickname) })
    }
  }, [display.nickname])

  /** 成绩列表请求：筛选变化重新请求，自增序号丢弃过期响应 */
  const loadHistory = useCallback(
    async (f: { rounds: number; mode: HistoryMode; dimension: string; precision: string; chasePeriods: string }) => {
      const seq = ++historySeqRef.current
      setHistoryLoading(true)
      setHistoryError('')
      try {
        const list = await fetchExpertHistory({
          userId: expertId,
          rounds: f.rounds,
          mode: f.mode,
          dimension: f.dimension || undefined,
          precision: f.precision || undefined,
          chasePeriods: f.mode === 'plan' && f.chasePeriods ? f.chasePeriods : undefined,
        })
        if (seq !== historySeqRef.current) return
        setCycles(list || [])
        setExpandedIds({})
      } catch (err: any) {
        if (seq !== historySeqRef.current) return
        setCycles([])
        setHistoryError(err?.message || expertLabels.history.loadFailed)
      } finally {
        if (seq === historySeqRef.current) setHistoryLoading(false)
      }
    },
    [expertId],
  )

  useEffect(() => {
    loadHistory({ rounds, mode, dimension, precision, chasePeriods })
  }, [rounds, mode, dimension, precision, chasePeriods, loadHistory])

  // 单期/计划数据可用性探测（按可用性禁用分段）
  useEffect(() => {
    let cancelled = false
    Promise.all(
      (['single', 'plan'] as HistoryMode[]).map((m) =>
        fetchExpertHistory({ userId: expertId, rounds, mode: m })
          .then((list) => ({ mode: m, ok: (list || []).length > 0 }))
          .catch(() => ({ mode: m, ok: false })),
      ),
    ).then((results) => {
      if (cancelled) return
      const modes = results.filter((item) => item.ok).map((item) => item.mode)
      if (modes.length === 0) return
      setAvailableModes(modes)
      setMode((prev) => (modes.includes(prev) ? prev : modes.includes('plan') ? 'plan' : modes[0]))
    })
    return () => {
      cancelled = true
    }
  }, [expertId, rounds])

  useEffect(() => {
    loadProfile()
  }, [loadProfile])

  usePullDownRefresh(async () => {
    await Promise.all([loadProfile(), loadHistory({ rounds, mode, dimension, precision, chasePeriods })])
    Taro.stopPullDownRefresh()
  })

  const pickDimension = useCallback((value: string) => {
    setDimension(value)
    // 维度变化后精准筛选选项失效自动清空
    setPrecision((prev) => (prev && !getPrecisionOptions(value as DimensionCode | '').includes(prev) ? '' : prev))
  }, [])

  const toggleExpand = useCallback((id: string) => {
    setExpandedIds((prev) => ({ ...prev, [id]: !prev[id] }))
  }, [])

  const precisionOptions = dimension ? getPrecisionOptions(dimension as DimensionCode) : []
  const starCount = Math.max(0, Math.min(5, Math.round(display.rating)))
  const pillCount = Math.max(0, Math.min(3, display.consecutiveWins))

  return (
    <View className='expert-page'>
      {/* 资料卡 */}
      <View className='profile-card'>
        {profileLoading ? (
          <Skeleton rows={1} card={false} />
        ) : (
          <>
            <View className='profile-card__top'>
              <Avatar src={display.avatar} name={display.nickname} size={64} />
              <View className='profile-card__info'>
                <View className='profile-card__name-row'>
                  <Text className='profile-card__name'>{display.nickname}</Text>
                  {display.isVerified ? <Text className='tag tag--verified'>{expertLabels.verified}</Text> : null}
                  <Text className='tag tag--data'>{expertLabels.dataVerified}</Text>
                </View>
                <View className='profile-card__stats'>
                  <Text className='profile-card__stat'>{expertLabels.fans(userInfo?.followerCount ?? 0)}</Text>
                  <Text className='profile-card__stat profile-card__stat--link' onClick={() => goExpertPosts(expertId)}>
                    {expertLabels.posts(userInfo?.forumCount ?? 0)}
                  </Text>
                  <Text
                    className='profile-card__stat profile-card__stat--link'
                    onClick={() => goExpertPosts(expertId, 'prediction')}
                  >
                    {expertLabels.forecasts(userInfo?.forecastCount ?? 0)}
                  </Text>
                </View>
              </View>
            </View>
            <View className='profile-card__actions'>
              <FollowButton
                key={`${display.id}-${followed}`}
                userId={display.id}
                isFollowed={followed}
                onChange={setFollowed}
              />
            </View>
          </>
        )}
      </View>

      {/* 三项统计卡横排 */}
      <View className='stats-row'>
        <View className='stat-card'>
          <Text className='stat-card__label'>{expertLabels.stats.winRate}</Text>
          <Text className='stat-card__value stat-card__value--accent'>{display.winRate}%</Text>
        </View>
        <View className='stat-card'>
          <Text className='stat-card__label'>{expertLabels.stats.consecutive}</Text>
          <View className='stat-card__value-row'>
            <Text className='stat-card__value'>{expertLabels.stats.consecutiveText(display.consecutiveWins)}</Text>
            {Array.from({ length: pillCount }).map((_, idx) => (
              <Text key={idx} className='streak-pill'>
                {expertLabels.stats.hitPill}
              </Text>
            ))}
          </View>
        </View>
        <View className='stat-card'>
          <Text className='stat-card__label'>{expertLabels.stats.rating}</Text>
          <View className='stat-card__value-row'>
            {[1, 2, 3, 4, 5].map((i) => (
              <Text key={i} className={`star${i <= starCount ? ' star--on' : ''}`}>
                ★
              </Text>
            ))}
            <Text className='stat-card__rating-num'>{display.rating}</Text>
          </View>
        </View>
      </View>

      {/* 历史成绩回顾 */}
      <View className='history-section'>
        <View className='history-section__head'>
          <Text className='history-section__title'>{expertLabels.history.title}</Text>
          <View className='history-section__filter' onClick={() => setPanelVisible(true)}>
            <Text className='history-section__filter-text'>{expertLabels.history.filter}</Text>
          </View>
        </View>

        {/* 单期/计划分段（按数据可用性禁用） */}
        <View className='segment'>
          {(['single', 'plan'] as HistoryMode[]).map((m) => {
            const disabled = !availableModes.includes(m)
            return (
              <View
                key={m}
                className={`segment__item${mode === m ? ' segment__item--active' : ''}${disabled ? ' segment__item--disabled' : ''}`}
                onClick={() => {
                  if (!disabled) setMode(m)
                }}
              >
                <Text
                  className={`segment__text${mode === m ? ' segment__text--active' : ''}${disabled ? ' segment__text--disabled' : ''}`}
                >
                  {m === 'single' ? expertLabels.history.modeSingle : expertLabels.history.modePlan}
                </Text>
              </View>
            )
          })}
        </View>

        {historyLoading && cycles.length === 0 ? (
          <Skeleton rows={3} />
        ) : historyError && cycles.length === 0 ? (
          <Empty
            text={historyError}
            actionText={commonLabels.networkError}
            onAction={() => loadHistory({ rounds, mode, dimension, precision, chasePeriods })}
          />
        ) : cycles.length === 0 ? (
          <Empty text={expertLabels.history.empty} />
        ) : (
          cycles.map((cycle) => {
            const expanded = !!expandedIds[cycle.id]
            const miss = isMissResult(cycle.resultLabel)
            return (
              <View key={cycle.id} className='cycle-card'>
                <View className='cycle-card__main'>
                  <View className='cycle-card__info'>
                    <Text className='cycle-card__period'>{cycle.periodRange}</Text>
                    <Text className='cycle-card__code'>{cycle.planCode}</Text>
                  </View>
                  <View className='cycle-card__side'>
                    <Text className={`cycle-card__result${miss ? ' cycle-card__result--miss' : ''}`}>
                      {cycle.resultLabel}
                    </Text>
                    <View className='cycle-card__toggle' onClick={() => toggleExpand(cycle.id)}>
                      <Text className='cycle-card__toggle-text'>
                        {expanded ? expertLabels.history.collapse : expertLabels.history.expand}
                      </Text>
                    </View>
                  </View>
                </View>
                {expanded ? (
                  <View className='cycle-card__issues'>
                    {cycle.issues.map((issue) => (
                      <View key={issue.issue} className='issue-row'>
                        <Text className='issue-row__no'>{issue.issue}</Text>
                        <View className='issue-row__balls'>
                          {issue.numbers.map((num, idx) => (
                            <Text key={`${issue.issue}-${idx}`} className={`ball${issue.hit ? ' ball--hit' : ' ball--miss'}`}>
                              {num}
                            </Text>
                          ))}
                        </View>
                      </View>
                    ))}
                  </View>
                ) : null}
              </View>
            )
          })
        )}
      </View>

      {/* 历史成绩筛选弹层：轮数 / 维度 / 精准筛选 / 追号期数（仅计划），点选即生效 */}
      <Popup visible={panelVisible} position='bottom' round destroyOnClose onClose={() => setPanelVisible(false)}>
        <View className='panel'>
          <Text className='panel__title'>{expertLabels.history.title}</Text>
          <View className='panel__group'>
            <Text className='panel__label'>{expertLabels.history.groups.rounds}</Text>
            <View className='panel__chips'>
              {EXPERT_HISTORY_ROUNDS_OPTIONS.map((n) => (
                <View key={n} className={`chip${rounds === n ? ' chip--active' : ''}`} onClick={() => setRounds(n)}>
                  <Text className={`chip__text${rounds === n ? ' chip__text--active' : ''}`}>
                    {expertLabels.history.roundsLabel(n)}
                  </Text>
                </View>
              ))}
            </View>
          </View>
          <View className='panel__group'>
            <Text className='panel__label'>{expertLabels.history.groups.dimension}</Text>
            <View className='panel__chips'>
              <View className={`chip${dimension === '' ? ' chip--active' : ''}`} onClick={() => pickDimension('')}>
                <Text className={`chip__text${dimension === '' ? ' chip__text--active' : ''}`}>
                  {expertLabels.history.all}
                </Text>
              </View>
              {['-2', '2', '3', '4', '5'].map((value) => (
                <View
                  key={value}
                  className={`chip${dimension === value ? ' chip--active' : ''}`}
                  onClick={() => pickDimension(value)}
                >
                  <Text className={`chip__text${dimension === value ? ' chip__text--active' : ''}`}>
                    {getDimensionLabel(value)}
                  </Text>
                </View>
              ))}
            </View>
          </View>
          {precisionOptions.length > 0 ? (
            <View className='panel__group'>
              <Text className='panel__label'>{expertLabels.history.groups.precision}</Text>
              <View className='panel__chips'>
                <View className={`chip${precision === '' ? ' chip--active' : ''}`} onClick={() => setPrecision('')}>
                  <Text className={`chip__text${precision === '' ? ' chip__text--active' : ''}`}>
                    {expertLabels.history.all}
                  </Text>
                </View>
                {precisionOptions.map((value) => (
                  <View
                    key={value}
                    className={`chip${precision === value ? ' chip--active' : ''}`}
                    onClick={() => setPrecision(value)}
                  >
                    <Text className={`chip__text${precision === value ? ' chip__text--active' : ''}`}>{value}</Text>
                  </View>
                ))}
              </View>
            </View>
          ) : null}
          {mode === 'plan' ? (
            <View className='panel__group'>
              <Text className='panel__label'>{expertLabels.history.groups.chase}</Text>
              <View className='panel__chips'>
                <View className={`chip${chasePeriods === '' ? ' chip--active' : ''}`} onClick={() => setChasePeriods('')}>
                  <Text className={`chip__text${chasePeriods === '' ? ' chip__text--active' : ''}`}>
                    {expertLabels.history.all}
                  </Text>
                </View>
                {EXPERT_CHASE_OPTIONS.map((n) => (
                  <View
                    key={n}
                    className={`chip${chasePeriods === String(n) ? ' chip--active' : ''}`}
                    onClick={() => setChasePeriods(String(n))}
                  >
                    <Text className={`chip__text${chasePeriods === String(n) ? ' chip__text--active' : ''}`}>
                      {expertLabels.history.chaseLabel(n)}
                    </Text>
                  </View>
                ))}
              </View>
            </View>
          ) : null}
          <View className='panel__footer'>
            <View className='panel__btn panel__btn--primary' onClick={() => setPanelVisible(false)}>
              <Text className='panel__btn-text panel__btn-text--primary'>{expertLabels.history.done}</Text>
            </View>
          </View>
        </View>
      </Popup>
    </View>
  )
}
