/**
 * 画规绘制引擎 · RN 端（react-native-svg + PanResponder）。
 * 与 engine.h5.tsx 同签名渲染同一形状模型；全量高度渲染（无 H5 视窗化），
 * 手势由 PanResponder 换算棋盘坐标。智能线曲线用二次贝塞尔近似
 * （Konva tension 样条经过控制点，贝塞尔控制点换算 c' = 2c - 中点）。
 * 降级项：文字旋转/缩放/透明度控制钮与控制点图标细节从简（保留拖拽移动、
 * 长按编辑、选中框、智能线控制点拖拽）。
 */
import { forwardRef, useImperativeHandle, useMemo, useRef, useState } from 'react'
import { PanResponder, View as RNView, type PanResponderGestureState } from 'react-native'
import Svg, { Circle, Ellipse, G, Path, Polyline, Rect, Text as SvgText, TSpan } from 'react-native-svg'
import { drawRuleLabels } from '@/labels/tools'
import {
  BOARD_COLORS,
  SMART_CONTROL_ICON_COLOR,
  TEXT_DEFAULT_HEIGHT,
  TEXT_FONT_SIZE,
  colorWithAlpha,
  exportContentTopY,
  hitTestDrawItem,
  isRearDigitColumnByCount,
  isSectionEndRow,
  measureTextItemWidth,
  pointDistance,
  predictionTextLines,
  rearDigitStartIndexFromCount,
  smartDraftRenderPoints,
  smartLineControlPoint,
  smartLineRenderPoints,
  stablePredictionColumns,
  textItemCenterFromTopLeft,
  type BoardGeometry,
  type BoardRow,
  type DigitCellTarget,
  type DrawEngineProps,
  type DrawEngineRef,
  type DrawItem,
  type DrawPoint,
  type PredictionRenderMark,
} from './model'

const TAP_DISTANCE = 10
const LONG_PRESS_DELAY = 500
const CONTROL_HIT_RADIUS = 28

type GestureMode = 'idle' | 'board' | 'item' | 'control'

interface GestureState {
  mode: GestureMode
  itemId?: string
  itemStart?: DrawPoint
  startPoint: DrawPoint
  lastPoint: DrawPoint
  moved: boolean
  dragging: boolean
  longPressFired: boolean
  longPressTimer?: ReturnType<typeof setTimeout>
}

const initialGesture: GestureState = {
  mode: 'idle',
  startPoint: { x: 0, y: 0 },
  lastPoint: { x: 0, y: 0 },
  moved: false,
  dragging: false,
  longPressFired: false,
}

/** 智能线渲染点（6 点=含控制点）→ svg path（控制点换算为贝塞尔控制点） */
function linePathData(points: number[]) {
  if (points.length === 6) {
    const [sx, sy, cx, cy, ex, ey] = points
    const bx = 2 * cx - (sx + ex) / 2
    const by = 2 * cy - (sy + ey) / 2
    return `M ${sx} ${sy} Q ${bx} ${by} ${ex} ${ey}`
  }
  return ''
}

function polylinePoints(points: number[]) {
  const pairs: string[] = []
  for (let i = 0; i + 1 < points.length; i += 2) {
    pairs.push(`${points[i]},${points[i + 1]}`)
  }
  return pairs.join(' ')
}

const DrawEngine = forwardRef<DrawEngineRef, DrawEngineProps>(function DrawEngine(props, ref) {
  const propsRef = useRef(props)
  propsRef.current = props
  const gestureRef = useRef<GestureState>({ ...initialGesture })
  const exportSvgRef = useRef<Svg | null>(null)
  const exportResolverRef = useRef<((value: string | null) => void) | null>(null)
  const [exporting, setExporting] = useState(false)

  const geometry = props.geometry

  // ---------- 手势 ----------

  function pointFromEvent(event: any): DrawPoint {
    return {
      x: Number(event?.nativeEvent?.locationX || 0),
      y: Number(event?.nativeEvent?.locationY || 0),
    }
  }

  function clearLongPress() {
    const gesture = gestureRef.current
    if (gesture.longPressTimer) {
      clearTimeout(gesture.longPressTimer)
      gesture.longPressTimer = undefined
    }
  }

  function activeSmartControlPoint(): { id: string; point: DrawPoint } | null {
    const p = propsRef.current
    if (!p.smartPenEnabled || !p.activeSmartControlLineId) return null
    const item = p.items.find((entry) => entry.id === p.activeSmartControlLineId)
    if (!item || item.type !== 'polyline' || item.lineKind !== 'smart') return null
    const control = smartLineControlPoint(item, p.geometry, p.rows, p.drawCount)
    if (!control) return null
    return { id: item.id, point: control }
  }

  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => propsRef.current.interactive,
        onMoveShouldSetPanResponder: () => propsRef.current.interactive,
        onPanResponderGrant: (event) => {
          const p = propsRef.current
          const point = pointFromEvent(event)
          const gesture: GestureState = {
            ...initialGesture,
            startPoint: point,
            lastPoint: point,
          }
          gestureRef.current = gesture

          // 智能线控制点优先
          const control = activeSmartControlPoint()
          if (control && pointDistance(point, control.point) <= CONTROL_HIT_RADIUS) {
            gesture.mode = 'control'
            gesture.itemId = control.id
            return
          }

          const tool = p.activeTool
          const cellTool = tool === '智能线' || tool === '直线'
          const hitItem = hitTestDrawItem(p.items, point, p.geometry, p.rows, p.drawCount)
          // 单元格工具（智能线/直线）按压非文字图形时按棋盘处理（源 Konva stage mousedown
          // 不区分图形命中，可在已有图形上起笔智能线）；按压文字则交给文字交互
          // （源 isTextInteractionTarget 提前返回，不触发智能线吸附）
          const treatAsItem = Boolean(hitItem && (!cellTool || hitItem.type === 'text'))
          if (hitItem && treatAsItem) {
            gesture.mode = 'item'
            gesture.itemId = hitItem.id
            gesture.itemStart = { x: hitItem.x || 0, y: hitItem.y || 0 }
            if (hitItem.type === 'text') {
              gesture.longPressTimer = setTimeout(() => {
                const current = gestureRef.current
                if (current.moved || current.mode !== 'item') return
                current.longPressFired = true
                propsRef.current.onTextEdit(hitItem.id)
              }, LONG_PRESS_DELAY)
            }
            return
          }

          gesture.mode = 'board'
          p.onPointerDown(point, { type: 'board' })
        },
        onPanResponderMove: (event, gestureState: PanResponderGestureState) => {
          const p = propsRef.current
          const gesture = gestureRef.current
          const point = pointFromEvent(event)
          gesture.lastPoint = point
          if (Math.abs(gestureState.dx) > TAP_DISTANCE || Math.abs(gestureState.dy) > TAP_DISTANCE) {
            gesture.moved = true
            clearLongPress()
          }
          if (gesture.mode === 'control' && gesture.itemId) {
            p.onSmartControlDrag(gesture.itemId, point, false)
            return
          }
          if (gesture.mode === 'item' && gesture.itemId && gesture.itemStart) {
            const item = p.items.find((entry) => entry.id === gesture.itemId)
            if (item && item.type !== 'polyline' && gesture.moved) {
              gesture.dragging = true
              p.onItemDragMove?.(gesture.itemId, {
                x: gesture.itemStart.x + gestureState.dx,
                y: gesture.itemStart.y + gestureState.dy,
              })
            }
            return
          }
          if (gesture.mode === 'board') {
            p.onPointerMove(point)
          }
        },
        onPanResponderRelease: (event) => {
          const p = propsRef.current
          const gesture = gestureRef.current
          clearLongPress()
          const point = gesture.lastPoint
          if (gesture.mode === 'control' && gesture.itemId) {
            p.onSmartControlDrag(gesture.itemId, point, true)
          } else if (gesture.mode === 'item' && gesture.itemId) {
            if (gesture.dragging) {
              p.onItemDragEnd(gesture.itemId, gesture.itemStart
                ? {
                    x: gesture.itemStart.x + (point.x - gesture.startPoint.x),
                    y: gesture.itemStart.y + (point.y - gesture.startPoint.y),
                  }
                : point)
            } else if (!gesture.longPressFired) {
              p.onTap(point, { type: 'item', itemId: gesture.itemId })
            }
          } else if (gesture.mode === 'board') {
            p.onPointerUp(point)
            if (!gesture.moved) {
              p.onTap(point, { type: 'board' })
            }
          }
          gestureRef.current = { ...initialGesture }
          void event
        },
        onPanResponderTerminate: () => {
          const p = propsRef.current
          clearLongPress()
          if (gestureRef.current.mode === 'board') {
            p.onPointerUp(null)
          }
          gestureRef.current = { ...initialGesture }
        },
      }),
    [],
  )

  // ---------- 形状渲染 ----------

  function renderItem(item: DrawItem, offsetY: number, forExport: boolean) {
    const p = propsRef.current
    const { geometry: g, rows, drawCount } = p
    if (item.type === 'polyline' || item.type === 'freeLine') {
      const points = item.lineKind === 'smart'
        ? smartLineRenderPoints(item, g, rows, drawCount)
        : item.points || []
      if (points.length < 4) return null
      const ox = item.x || 0
      const oy = (item.y || 0) + offsetY
      const common = {
        stroke: item.stroke,
        strokeWidth: item.strokeWidth,
        strokeLinecap: 'round' as const,
        strokeLinejoin: 'round' as const,
        fill: 'none',
        strokeDasharray: item.dash ? item.dash.join(' ') : undefined,
      }
      const control =
        !forExport && p.smartPenEnabled && item.id === p.activeSmartControlLineId && item.lineKind === 'smart'
          ? smartLineControlPoint(item, g, rows, drawCount)
          : null
      return (
        <G key={item.id}>
          {points.length === 6 ? (
            <Path d={linePathData(points)} x={ox} y={oy} {...common} />
          ) : (
            <Polyline points={polylinePoints(points)} x={ox} y={oy} {...common} />
          )}
          {control ? renderControlIcon(control, g) : null}
        </G>
      )
    }
    if (item.type === 'circle') {
      const fallbackRadius = item.radius || 1
      return (
        <Ellipse
          key={item.id}
          cx={item.x || 0}
          cy={(item.y || 0) + offsetY}
          rx={item.radiusX || fallbackRadius}
          ry={item.radiusY || fallbackRadius}
          fill={item.fill || 'none'}
          stroke={item.stroke}
          strokeWidth={item.strokeWidth}
        />
      )
    }
    if (item.type === 'rect') {
      return (
        <Rect
          key={item.id}
          x={item.x || 0}
          y={(item.y || 0) + offsetY}
          width={item.width || 1}
          height={item.height || 1}
          fill={item.fill || 'none'}
          stroke={item.stroke}
          strokeWidth={item.strokeWidth}
        />
      )
    }
    // text
    const width = measureTextItemWidth(item)
    const height = item.height || TEXT_DEFAULT_HEIGHT
    const center = textItemCenterFromTopLeft(item, width, height)
    const scale = item.scale || 1
    const rotation = item.rotation || 0
    const selected = !forExport && item.id === p.activeTextItemId
    return (
      <G
        key={item.id}
        x={center.x}
        y={center.y + offsetY}
        rotation={rotation}
        scale={scale}
        origin={`${center.x}, ${center.y + offsetY}`}
      >
        {selected ? (
          <Rect
            x={-width / 2}
            y={-height / 2}
            width={width}
            height={height}
            stroke={item.stroke}
            strokeWidth={2 / scale}
            fill="rgba(255, 255, 255, 0.04)"
            strokeDasharray="6 4"
          />
        ) : null}
        {!item.textTransparent ? (
          <Rect
            x={-width / 2}
            y={-height / 2}
            width={width}
            height={height}
            rx={4}
            fill={item.stroke}
            opacity={item.opacity ?? 1}
          />
        ) : null}
        <SvgText
          x={0}
          y={TEXT_FONT_SIZE * 0.35}
          fill={item.textTransparent ? item.stroke : '#fff'}
          fontSize={TEXT_FONT_SIZE}
          fontWeight="bold"
          textAnchor="middle"
          opacity={item.textTransparent ? 1 : item.opacity ?? 1}
        >
          {item.text || ''}
        </SvgText>
      </G>
    )
  }

  function renderControlIcon(control: DrawPoint, g: BoardGeometry) {
    const iconScale = g.scale
    const iconRadius = Math.max(5, 7 * iconScale)
    const armDistance = Math.max(10, 15 * iconScale)
    const armLength = Math.max(6, 8 * iconScale)
    const armWidth = Math.max(3, 4 * iconScale)
    return (
      <G x={control.x} y={control.y}>
        <Circle r={iconRadius} fill={SMART_CONTROL_ICON_COLOR} stroke="#fff" strokeWidth={Math.max(1.5, 2 * iconScale)} />
        <Rect x={-armWidth / 2} y={-armDistance - armLength / 2} width={armWidth} height={armLength} fill={SMART_CONTROL_ICON_COLOR} rx={2} />
        <Rect x={-armWidth / 2} y={armDistance - armLength / 2} width={armWidth} height={armLength} fill={SMART_CONTROL_ICON_COLOR} rx={2} />
        <Rect x={-armDistance - armLength / 2} y={-armWidth / 2} width={armLength} height={armWidth} fill={SMART_CONTROL_ICON_COLOR} rx={2} />
        <Rect x={armDistance - armLength / 2} y={-armWidth / 2} width={armLength} height={armWidth} fill={SMART_CONTROL_ICON_COLOR} rx={2} />
      </G>
    )
  }

  function renderDigitMark(cell: DigitCellTarget, state: 'active' | 'preview', offsetY: number) {
    const g = propsRef.current.geometry
    const isPreview = state === 'preview'
    const markColor = cell.color || '#ff0707'
    const textLength = Array.from(cell.value || '').length
    const fontSize =
      textLength >= 3 ? Math.max(14, 20 * g.scale) : textLength === 2 ? Math.max(18, 26 * g.scale) : Math.max(22, 34 * g.scale)
    return (
      <G key={`${state}-${cell.key}`} x={cell.x} y={cell.y + offsetY} opacity={isPreview ? 0.82 : 1}>
        <Circle
          r={g.digitMarkRadius}
          fill={isPreview ? colorWithAlpha(markColor, 0.72) : markColor}
          stroke="#fff"
          strokeWidth={3}
        />
        {cell.value ? (
          <SvgText x={0} y={fontSize * 0.35} fill="#fff" fontSize={fontSize} fontWeight="bold" textAnchor="middle">
            {cell.value}
          </SvgText>
        ) : null}
      </G>
    )
  }

  function renderPredictionMark(mark: PredictionRenderMark, offsetY: number) {
    const p = propsRef.current
    const g = p.geometry
    const isStable = mark.condition === 'stable'
    const markScale = g.scale
    const width = isStable
      ? g.digitCellWidth * Math.max(1, stablePredictionColumns(p.drawCount).length) - 14 * markScale
      : Math.max(34, 46 * markScale)
    const height = Math.max(36, 54 * markScale)
    const isHollow = mark.fillMode === 'hollow'
    const markColor = mark.color || '#ff0707'
    const x = isStable ? g.digitStartX + 7 * markScale : mark.x - width / 2
    const y = mark.y - height / 2 + offsetY
    const lines = predictionTextLines(mark, drawRuleLabels.stablePrevCode)
    const fontSize = isStable ? Math.max(15, 24 * markScale) : Math.max(12, 16 * markScale)
    const lineHeight = fontSize * 1.05
    const textBlockHeight = lineHeight * lines.length
    const firstBaseline = height / 2 - textBlockHeight / 2 + fontSize * 0.85
    return (
      <G key={mark.id} x={x} y={y}>
        <Rect
          width={width}
          height={height}
          fill={isHollow ? '#fff' : markColor}
          stroke={markColor}
          strokeWidth={isHollow ? 2 : 0}
          rx={1}
        />
        <SvgText fill={isHollow ? markColor : '#fff'} fontSize={fontSize} fontWeight="bold" textAnchor="middle">
          {lines.map((line, index) => (
            <TSpan key={index} x={width / 2} y={firstBaseline + index * lineHeight}>
              {line}
            </TSpan>
          ))}
        </SvgText>
      </G>
    )
  }

  function renderDraft(offsetY: number) {
    const draft = propsRef.current.draft
    if (!draft) return null
    if (draft.kind === 'line' || draft.kind === 'freeLine') {
      return (
        <Polyline
          points={polylinePoints(draft.points)}
          y={offsetY}
          stroke={draft.stroke}
          strokeWidth={draft.strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          fill="none"
          strokeDasharray={draft.kind === 'line' && draft.dashed ? '10 6' : undefined}
        />
      )
    }
    if (draft.kind === 'smart') {
      return (
        <G y={offsetY}>
          {draft.segments.map((segment, index) => {
            const points = smartDraftRenderPoints(
              [segment.start.x, segment.start.y, segment.endPoint.x, segment.endPoint.y],
              draft.shape,
            )
            return points.length === 6 ? (
              <Path
                key={index}
                d={linePathData(points)}
                stroke={segment.color}
                strokeWidth={draft.strokeWidth}
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
              />
            ) : (
              <Polyline
                key={index}
                points={polylinePoints(points)}
                stroke={segment.color}
                strokeWidth={draft.strokeWidth}
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
              />
            )
          })}
        </G>
      )
    }
    if (draft.kind === 'ellipse') {
      return (
        <Ellipse
          cx={draft.x}
          cy={draft.y + offsetY}
          rx={draft.radiusX}
          ry={draft.radiusY}
          fill={draft.fill || 'none'}
          stroke={draft.stroke}
          strokeWidth={draft.strokeWidth}
          strokeDasharray={draft.dashed ? '10 6' : undefined}
        />
      )
    }
    return (
      <Rect
        x={draft.x}
        y={draft.y + offsetY}
        width={draft.width}
        height={draft.height}
        fill={draft.fill || 'none'}
        stroke={draft.stroke}
        strokeWidth={draft.strokeWidth}
        strokeDasharray={draft.dashed ? '10 6' : undefined}
      />
    )
  }

  // ---------- 导出（离屏 svg，含奖表背景） ----------

  useImperativeHandle(ref, () => ({
    capturePngDataURL() {
      return new Promise<string | null>((resolve) => {
        exportResolverRef.current = resolve
        setExporting(true)
      })
    },
  }))

  function handleExportLayout() {
    // 等待一帧让 svg 完成挂载后再取快照
    setTimeout(() => {
      const resolve = exportResolverRef.current
      exportResolverRef.current = null
      const done = (value: string | null) => {
        setExporting(false)
        resolve?.(value)
      }
      const svg = exportSvgRef.current
      if (!svg) {
        done(null)
        return
      }
      try {
        svg.toDataURL((base64: string) => {
          done(base64 ? `data:image/png;base64,${base64}` : null)
        })
      } catch {
        done(null)
      }
    }, 120)
  }

  function renderExportSvg() {
    const p = propsRef.current
    const g = p.geometry
    const topY = exportContentTopY(p.items, p.digitMarks, [], p.predictionMarks, g, p.rows, p.drawCount)
    const exportHeight = Math.max(g.rowHeight, g.boardHeight - topY)
    const offsetY = -topY
    const splitAfter = (() => {
      const rear = rearDigitStartIndexFromCount(p.drawCount)
      return rear > 0 ? rear - 1 : -1
    })()
    return (
      <RNView
        pointerEvents="none"
        style={{ position: 'absolute', left: -Math.ceil(g.boardWidth) - 200, top: 0 }}
        collapsable={false}
      >
        <Svg
          ref={exportSvgRef as any}
          width={Math.ceil(g.boardWidth)}
          height={Math.ceil(exportHeight)}
          onLayout={handleExportLayout}
        >
          <Rect x={0} y={0} width={g.boardWidth} height={exportHeight} fill={BOARD_COLORS.background} />
          {p.rows.map((row, rowIndex) => (
            <ExportRow
              key={row.key}
              row={row}
              rowIndex={rowIndex}
              geometry={g}
              drawCount={p.drawCount}
              splitAfter={splitAfter}
              offsetY={offsetY}
            />
          ))}
          {p.items.map((item) => renderItem(item, offsetY, true))}
          {p.digitMarks.map((cell) => renderDigitMark(cell, 'active', offsetY))}
          {p.predictionMarks.map((mark) => renderPredictionMark(mark, offsetY))}
        </Svg>
      </RNView>
    )
  }

  // ---------- 可见层 ----------

  return (
    <RNView
      style={{
        position: 'absolute',
        left: 0,
        top: 0,
        width: Math.ceil(geometry.boardWidth),
        height: Math.ceil(geometry.boardHeight),
      }}
      {...panResponder.panHandlers}
    >
      <Svg width={Math.ceil(geometry.boardWidth)} height={Math.ceil(geometry.boardHeight)}>
        {props.items.map((item) => renderItem(item, 0, false))}
        {props.digitMarks.map((cell) => renderDigitMark(cell, 'active', 0))}
        {props.predictionMarks.map((mark) => renderPredictionMark(mark, 0))}
        {props.previewStartCells.map((cell) => renderDigitMark(cell, 'active', 0))}
        {dedupeCells(props.previewTargetCells).map((cell) => renderDigitMark(cell, 'preview', 0))}
        {renderDraft(0)}
      </Svg>
      {exporting ? renderExportSvg() : null}
    </RNView>
  )
})

function dedupeCells(cells: DigitCellTarget[]) {
  const seen = new Set<string>()
  return cells.filter((cell) => {
    if (seen.has(cell.key)) return false
    seen.add(cell.key)
    return true
  })
}

/** 导出用单行奖表背景（与 board.tsx 视觉一致） */
function ExportRow({
  row,
  rowIndex,
  geometry,
  drawCount,
  splitAfter,
  offsetY,
}: {
  row: BoardRow
  rowIndex: number
  geometry: BoardGeometry
  drawCount: number
  splitAfter: number
  offsetY: number
}) {
  const g = geometry
  const y = rowIndex * g.rowHeight + offsetY
  if (y + g.rowHeight < 0 || y > g.boardHeight) return null
  const sectionEnd = isSectionEndRow(rowIndex)
  const bottomBorder = (
    <Path
      d={`M 0 ${y + g.rowHeight - (sectionEnd ? 1.5 : 0.5)} L ${g.boardWidth} ${y + g.rowHeight - (sectionEnd ? 1.5 : 0.5)}`}
      stroke={sectionEnd ? BOARD_COLORS.sectionBorder : BOARD_COLORS.border}
      strokeWidth={sectionEnd ? 3 : 1}
    />
  )
  return (
    <G>
      <Rect x={0} y={y} width={g.issueColumnWidth} height={g.rowHeight} fill={BOARD_COLORS.issueBackground} />
      {!row.placeholder && row.issue ? (
        <SvgText
          x={g.issueColumnWidth / 2}
          y={y + g.rowHeight * 0.4 + Math.max(11, 16 * g.scale) * 0.35}
          fill={BOARD_COLORS.issueText}
          fontSize={Math.max(11, 16 * g.scale)}
          fontWeight="bold"
          textAnchor="middle"
        >
          {row.issue}
        </SvgText>
      ) : null}
      {!row.placeholder && row.weekLabel ? (
        <SvgText
          x={g.issueColumnWidth / 2}
          y={y + g.rowHeight * 0.7 + Math.max(10, 12 * g.scale) * 0.35}
          fill={BOARD_COLORS.issueText}
          fontSize={Math.max(10, 12 * g.scale)}
          fontWeight="bold"
          textAnchor="middle"
        >
          {row.weekLabel}
        </SvgText>
      ) : null}
      <Rect
        x={g.issueColumnWidth}
        y={y}
        width={g.sumColumnWidth}
        height={g.rowHeight}
        fill={BOARD_COLORS.sumBackground}
        stroke={BOARD_COLORS.sumBorder}
        strokeWidth={0}
      />
      <Path
        d={`M ${g.digitStartX - 1} ${y} L ${g.digitStartX - 1} ${y + g.rowHeight}`}
        stroke={BOARD_COLORS.sumBorder}
        strokeWidth={2}
      />
      {!row.placeholder && row.sumText ? (
        <SvgText
          x={g.issueColumnWidth + g.sumColumnWidth / 2}
          y={y + g.rowHeight / 2 + Math.max(12, 16 * g.scale) * 0.35}
          fill={BOARD_COLORS.sumText}
          fontSize={Math.max(12, 16 * g.scale)}
          fontWeight="bold"
          textAnchor="middle"
        >
          {row.sumText}
        </SvgText>
      ) : null}
      {Array.from({ length: drawCount }, (_, columnIndex) => {
        const x = g.digitStartX + columnIndex * g.digitCellWidth
        const value = row.numbers[columnIndex] || ''
        const isSplit = columnIndex === splitAfter
        const fontSize = isRearDigitColumnByCount(drawCount, columnIndex)
          ? Math.max(18, 26 * g.scale)
          : Math.max(22, 34 * g.scale)
        return (
          <G key={columnIndex}>
            <Rect
              x={x}
              y={y}
              width={g.digitCellWidth}
              height={g.rowHeight}
              fill={value ? BOARD_COLORS.digitHitBackground : BOARD_COLORS.digitBackground}
            />
            <Path
              d={`M ${x + g.digitCellWidth - (isSplit ? 1.5 : 0.5)} ${y} L ${x + g.digitCellWidth - (isSplit ? 1.5 : 0.5)} ${y + g.rowHeight}`}
              stroke={isSplit ? BOARD_COLORS.splitBorder : BOARD_COLORS.border}
              strokeWidth={isSplit ? 3 : 1}
            />
            {value ? (
              <SvgText
                x={x + g.digitCellWidth / 2}
                y={y + g.rowHeight / 2 + fontSize * 0.35}
                fill={BOARD_COLORS.digitText}
                fontSize={fontSize}
                fontWeight="bold"
                textAnchor="middle"
              >
                {value}
              </SvgText>
            ) : null}
          </G>
        )
      })}
      {bottomBorder}
    </G>
  )
}

export default DrawEngine
