export const LOTTERY_OPTIONS = LOTTERY_LIST.map(({ label, code }) => ({ label, value: code }))

/** 非法彩种 code 一律回退排列五 */
export function normalizeLotteryCode(raw?: string | null): LotteryCode {
  const code = String(raw || '').trim() as LotteryCode
  return LOTTERY_LIST.some((item) => item.code === code) ? code : DEFAULT_LOTTERY_CODE
}

export function getLotteryMeta(raw?: string | null): LotteryMeta {
  return LOTTERY_LIST.find((item) => item.code === normalizeLotteryCode(raw))!
}

export function getLotteryLabel(raw?: string | null): string {
  return getLotteryMeta(raw).label
}

export function getSlugByLotteryCode(raw?: string | null): string {
  return getLotteryMeta(raw).slug
}

export function getLotteryCodeBySlug(slug?: string | null): LotteryCode | null {
  const normalized = String(slug || '').trim().toLowerCase()
  const found = LOTTERY_LIST.find((item) => item.slug === normalized)
  return found ? found.code : null
}

