/** 命中判定统一口径 */
export type HitStatus = 'hit' | 'miss' | 'pending'

export function resolveHitStatus(hitFlag?: string | null, hitDetailOverall?: string | null): HitStatus {
  const raw = String(hitFlag || hitDetailOverall || '').toLowerCase()
  if (raw === 'hit' || raw === 'success') return 'hit'
  if (raw === 'fail' || raw === 'miss') return 'miss'
  return 'pending'
}

/** 维度 planMode → 展示名 */
export function getDimensionLabel(planMode?: string | number): string {
  const value = String(planMode ?? '')
  switch (value) {
    case '-2':
    case '-1':
      return '一定'
    case '2':
      return '二定'
    case '3':
      return '三定'
    case '4':
      return '四定'
    case '5':
      return '五定'
    default:
      return ''
  }
}
