/**
 * 自由模式（valueType='0'）号码「大底 / 重点 / 主攻」分栏的序列化与解析。
 * 移植自 lottery_web utils/freeModeSections.ts；发布页提交、详情页展示、
 * 编辑还原三处必须共用本文件逻辑，保持行为一致。
 */

export interface FreeModeSections {
  base: string
  focus: string
  main: string
  hasMarkers: boolean
}

/** 把任意分隔符（空格/逗号/分号/换行，含全角）的号码串归一化为单空格分隔 */
export function normalizeNumberTokens(raw?: string | number | null): string {
  return String(raw || '')
    .split(/[\s,，;；]+/)
    .map((s) => s.trim())
    .filter(Boolean)
    .join(' ')
}

/** 大底号码的最少个数 */
export const FREE_MODE_BASE_MIN = 10
/** 重点栏数量上限占大底数量的比例（向下取整） */
export const FREE_MODE_FOCUS_RATIO = 0.7
/** 主攻栏数量上限占大底数量的比例（向下取整） */
export const FREE_MODE_MAIN_RATIO = 0.2

/** 号码 token 必须是纯数字（如 01、12） */
const NUMBER_TOKEN_RE = /^\d+$/

export function splitNumberTokens(raw?: string | number | null): string[] {
  const normalized = normalizeNumberTokens(raw)
  return normalized ? normalized.split(' ') : []
}

/** 统计号码个数：仅计纯数字 token，且按 token 文本去重（'1' 与 '01' 视为不同） */
export function countNumberTokens(raw?: string | number | null): number {
  return new Set(splitNumberTokens(raw).filter((t) => NUMBER_TOKEN_RE.test(t))).size
}

/** 返回串中的非数字 token（去重、保持出现顺序），用于校验提示 */
export function findNonNumericTokens(raw?: string | number | null): string[] {
  return Array.from(new Set(splitNumberTokens(raw).filter((t) => !NUMBER_TOKEN_RE.test(t))))
}

/** 合并多段号码串为单空格分隔（提交时写入 diffuseValue） */
export function combineNumberTokens(...parts: (string | undefined)[]): string {
  return parts
    .flatMap((p) =>
      String(p || '')
        .split(/[\s,，;；]+/)
        .map((s) => s.trim())
        .filter(Boolean),
    )
    .join(' ')
}

/** 从 summarize 中截取【预测数据】段（到【数据总结】或文末为止）；无标记时返回全文 */
export function extractPredictionDataSection(summarize?: string | null): string {
  const text = String(summarize || '')
  const m = text.match(/【预测数据】\s*([\s\S]*?)(?:【数据总结】|$)/)
  return m ? m[1].trim() : text.trim()
}

/** 从 summarize 中截取【数据总结】段；无标记时返回空串 */
export function extractSummarySection(summarize?: string | null): string {
  const text = String(summarize || '')
  const m = text.match(/【数据总结】\s*([\s\S]*)$/)
  return m ? m[1].trim() : ''
}

/** 三栏序列化为多行标记文本（空栏省略） */
export function serializeFreeModeSections(base: string, focus: string, main: string): string {
  const parts: string[] = []
  const b = normalizeNumberTokens(base)
  const f = normalizeNumberTokens(focus)
  const m = normalizeNumberTokens(main)
  if (b) parts.push(`大底：${b}`)
  if (f) parts.push(`重点：${f}`)
  if (m) parts.push(`主攻：${m}`)
  return parts.join('\n')
}

/**
 * 解析 summarize 中的分栏标记。
 * - 有标记：严格按标记归栏，标记行之后的续行并入该栏
 * - 无标记（旧帖）：全部归入 base，hasMarkers=false
 */
export function parseFreeModeSections(summarize?: string | null): FreeModeSections {
  const text = extractPredictionDataSection(summarize)
  const sections = { base: '', focus: '', main: '' }
  let current: 'base' | 'focus' | 'main' | null = null
  text.split('\n').forEach((line) => {
    const labelMatch = line.match(/^\s*(大底|重点|主攻)[：:]\s*(.*)$/)
    if (labelMatch) {
      const label = labelMatch[1]
      current = label === '大底' ? 'base' : label === '重点' ? 'focus' : 'main'
      const rest = labelMatch[2].trim()
      if (rest) sections[current] += (sections[current] ? ' ' : '') + rest
    } else if (current && line.trim()) {
      sections[current] += (sections[current] ? ' ' : '') + line.trim()
    } else if (line.trim()) {
      sections.base += (sections.base ? ' ' : '') + line.trim()
    }
  })
  return {
    base: normalizeNumberTokens(sections.base),
    focus: normalizeNumberTokens(sections.focus),
    main: normalizeNumberTokens(sections.main),
    hasMarkers: text.includes('大底') || text.includes('重点') || text.includes('主攻'),
  }
}

/** 发布页「编辑还原」专用：有标记严格分栏；无标记回退 diffuseValue */
export function parseFreeModeSectionsForEdit(
  summarize?: string | null,
  diffuseValue?: string | null,
): { base: string; focus: string; main: string } {
  const sections = parseFreeModeSections(summarize)
  return {
    base: sections.hasMarkers ? sections.base : sections.base || String(diffuseValue || ''),
    focus: sections.focus,
    main: sections.main,
  }
}

/** 详情页「复制号码」文本 */
export function buildFreeModeCopyText(
  summarize?: string | null,
  diffuseValue?: string | null,
): string {
  const sections = parseFreeModeSections(summarize)
  if (sections.hasMarkers) {
    const text = serializeFreeModeSections(sections.base, sections.focus, sections.main)
    if (text) return text
  }
  return normalizeNumberTokens(diffuseValue)
}
