.posts-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.posts-page__title {
  display: block;
  padding: 16px 16px 8px;
  font-size: 17px;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 双 Tab 分段 */
.tabs {
  display: flex;
  flex-direction: row;
  background: var(--color-bg-card);
  padding: 8px 16px;
  gap: 8px;
  margin-bottom: 12px;
}

.tabs__item {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  border-radius: var(--radius-sm);
}

.tabs__item--active {
  background: var(--color-primary-light);
}

.tabs__text {
  font-size: 15px;
  color: var(--color-text-secondary);
}

.tabs__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

/* 交流帖行 */
.post-row {
  margin: 0 16px 12px;
  padding: 16px 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.post-row__title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.post-row__meta {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 10px;
}

.post-row__author {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin: 0 8px;
  max-width: 96px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.post-row__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 12px;
}

.post-row__time {
  font-size: 12px;
  color: var(--color-text-placeholder);
  margin-left: auto;
}

/* 预测帖卡片 */
.pred-card {
  margin: 0 16px 12px;
  padding: 16px 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.pred-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.pred-card__author {
  flex: 1;
  min-width: 0;
  margin-left: 10px;
}

.pred-card__name {
  display: block;
  font-size: 14px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pred-card__time {
  display: block;
  font-size: 12px;
  color: var(--color-text-placeholder);
  margin-top: 2px;
}

.pred-card__title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  margin-top: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pred-card__footer {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
}

.pred-card__tags {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.pred-card__dim {
  font-size: 11px;
  color: var(--color-info);
  background: rgba(52, 152, 219, 0.1);
  border-radius: 4px;
  padding: 2px 8px;
  margin-right: 8px;
}

.pred-card__stats {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.pred-card__stat {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-left: 12px;
}

.list-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
}

.list-footer__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}
