import Taro from '@tarojs/taro'
import { STORAGE_KEYS } from '@/utils/storage'

/**
 * 统一请求封装（产品方案 §5.2）：
 * - baseURL 走环境配置（XHS_API_BASE，dev 默认直连 Java 后端 http://127.0.0.1:9081）
 * - 认证头 bizAuthorization 从 storage 注入
 * - 超时 15s；GET 重试 1 次；POST 不重试
 * - 成功码：普通接口 code===200；分页表格接口 code 0 或 200（RuoYi 双兼容）
 * - 错误提示取值顺序：msg → message
 * - 401 清会话并跳登录；403 仅提示
 */

export class ApiError extends Error {
  status: number
  code?: number
  data?: any

  constructor(message: string, status = 0, code?: number, data?: any) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
    this.data = data
  }
}

export interface RequestOptions {
  url: string
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
  data?: Record<string, any>
  /** 是否分页接口（成功码 0/200 双兼容，兼容 rows/total 双结构） */
  paged?: boolean
  /** 401 时是否静默（不跳登录），默认 false */
  silent401?: boolean
}

const TIMEOUT = 15000

type UnauthorizedHandler = () => void
let onUnauthorized: UnauthorizedHandler | null = null

/** 由 auth store 注册：401 时清除会话 */
export function setUnauthorizedHandler(handler: UnauthorizedHandler) {
  onUnauthorized = handler
}

/**
 * 当前会话 token 的内存缓存（权威值），null 表示尚未从 storage 加载。
 * storage 仅用于跨启动持久化：登录/登出后内存值立即生效，
 * 避免 RN AsyncStorage 异步落盘与后续读取之间的竞态。
 */
let memoryToken: string | null = null

export async function getToken(): Promise<string> {
  // RN 端不支持 *StorageSync，统一走异步 API
  if (memoryToken !== null) return memoryToken
  try {
    const res = await Taro.getStorage({ key: STORAGE_KEYS.token })
    memoryToken = String(res.data || '')
  } catch {
    memoryToken = ''
  }
  return memoryToken
}

export function setToken(token: string, persist = true) {
  memoryToken = token
  if (persist) {
    Taro.setStorage({ key: STORAGE_KEYS.token, data: token }).catch(() => {})
  } else {
    Taro.removeStorage({ key: STORAGE_KEYS.token }).catch(() => {})
  }
}

export function clearToken() {
  memoryToken = ''
  Taro.removeStorage({ key: STORAGE_KEYS.token }).catch(() => {})
}

function pickErrorMessage(data: any, fallback: string): string {
  return String(data?.msg || data?.message || fallback)
}

/**
 * AjaxResult 解包兜底：doRequest 在 data 缺失时会回退返回整个 body（{code,msg}），
 * 调用方需要「data 直透」语义时用它统一取 data（缺失则为 undefined）。
 */
export function unwrapAjaxData<T = any>(payload: any): T {
  if (payload && typeof payload === 'object' && 'code' in payload && 'msg' in payload) {
    return payload.data as T
  }
  return payload as T
}

/** 分页结构双兼容：rows/total 可能在顶层或包在 data 中 */
function unwrapPaged(payload: any): { rows: any[]; total: number } {
  const box = payload?.data && Array.isArray(payload?.data?.rows) ? payload.data : payload
  return {
    rows: Array.isArray(box?.rows) ? box.rows : [],
    total: Number(box?.total ?? 0),
  }
}

async function doRequest<T = any>(options: RequestOptions): Promise<T> {
  const { url, method = 'GET', data, paged = false, silent401 = false } = options
  const token = await getToken()

  const header: Record<string, string> = {}
  if (token) header['bizAuthorization'] = token

  let res
  try {
    res = await Taro.request({
      url: `${XHS_API_BASE}${url}`,
      method,
      data,
      header,
      timeout: TIMEOUT,
    })
  } catch (err: any) {
    throw new ApiError('网络异常，请稍后重试', 0)
  }

  const status = res.statusCode
  const body = res.data as any

  if (status === 401 || body?.code === 401) {
    if (!silent401) {
      clearToken()
      onUnauthorized?.()
    }
    throw new ApiError(pickErrorMessage(body, '登录状态已失效，请重新登录'), 401, body?.code, body)
  }

  if (status === 403 || body?.code === 403) {
    throw new ApiError(pickErrorMessage(body, '没有权限执行该操作'), 403, body?.code, body)
  }

  if (status < 200 || status >= 300) {
    throw new ApiError(pickErrorMessage(body, `请求失败（${status}）`), status, body?.code, body)
  }

  // AjaxResult { code, msg, data }：普通接口成功码 200；分页接口 0 或 200
  if (body && typeof body === 'object' && 'code' in body) {
    const ok = body.code === 200 || (paged && body.code === 0)
    if (!ok) {
      const msg = pickErrorMessage(body, '请求失败')
      throw new ApiError(msg, mapCodeToStatus(body.code), body.code, body)
    }
    if (paged) return unwrapPaged(body) as unknown as T
    return (body.data === undefined ? body : body.data) as T
  }

  if (paged) return unwrapPaged(body) as unknown as T
  return body as T
}

function mapCodeToStatus(code?: number): number {
  if (code === 401 || code === 403) return code
  if (typeof code === 'number' && code >= 500) return 500
  return 400
}

export async function request<T = any>(options: RequestOptions): Promise<T> {
  try {
    return await doRequest<T>(options)
  } catch (err) {
    // GET 网络层错误重试 1 次；POST/PUT/DELETE 不重试；业务错误不重试
    if (options.method === undefined || options.method === 'GET') {
      if (err instanceof ApiError && err.status === 0) {
        return await doRequest<T>(options)
      }
    }
    throw err
  }
}

export function get<T = any>(url: string, data?: Record<string, any>, opts?: Partial<RequestOptions>) {
  return request<T>({ url, method: 'GET', data, ...opts })
}

export function post<T = any>(url: string, data?: Record<string, any>, opts?: Partial<RequestOptions>) {
  return request<T>({ url, method: 'POST', data, ...opts })
}

export function put<T = any>(url: string, data?: Record<string, any>, opts?: Partial<RequestOptions>) {
  return request<T>({ url, method: 'PUT', data, ...opts })
}

export function del<T = any>(url: string, data?: Record<string, any>, opts?: Partial<RequestOptions>) {
  return request<T>({ url, method: 'DELETE', data, ...opts })
}
